insert into locations (id, case_id, name, image_url, preview_image_url, short_description, map_pos_x, map_pos_y, is_searchable, unlock_evidence_ids, pano_haov, search_note) values ('92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'База и офис фирмы на Ташкентской', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-baza-wide.jpg', 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-baza-tashkentskaya.jpg', 'Ташкентская. Бывшая госбаза: бетонный забор, шлагбаум, будка КПП.', 59.8, 53.9, true, array['54bf13bc-3525-5eec-9441-609d8ee21f59','7ada2011-2720-5b69-8a9c-9291fdad70e9']::uuid[], 180, 'Осмотр ничего не дал. Слишком чисто для конторы, где идёт торговля: пол вымыт, корзины пустые, на столах ни бумажки. Тут прибрались до вас. Спрашивайте людей.');
