-- 4. Персонажи
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, is_expert, is_suspect, is_case_subject, portrait_url) values ('57949d2d-0b2d-5c04-812c-5849e9441857', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Начальник следственного отдела', 'ГУВД г. Алматы', 'Несчастный случай. Так решил Медеуский РОВД.

Понедельник, 25 ноября 1996 года, 9:10. Кабинет начальника следственного отдела ГУВД г. Алматы.

— Садись. Пальто не снимай, батарея всё равно не греет.
Вот. Подарок из Медеуского РОВД, отказной материал.
Сартаков Игорь, сорок один год. Хозяин базы на Ташкентской, импорт оборудования. Вчера в 09:40 его водитель, Гринько, нашёл. В гараже, на собственной даче, на Кок-Тобе. За рулём. Ключ в зажигании, бак сухой, ворота гаража закрыты. А в субботу вечером на Кок-Тобе отключали свет. Ну и вот: грелся в машине, задремал, угорел.
Опергруппа управилась за час. Вскрытие не назначили: «и так ясно». Мать хочет хоронить. РОВД хочет закрыть. Прокуратура хочет, чтобы я подписал.
А я не подпишу. Пока ты не посмотришь. Мужик при деньгах, в разводе, база приватизированная. Такие у нас сами редко умирают.
Тело в морге, Юрий Николаевич Кан ждёт бумагу. Гульнара Сеитова съездит с тобой на дачу. Ринат Абишев посидит на картотеках. Доцент Бейсенов из высшей школы МВД на этой неделе у нас консультирует.
Даю неделю. Угорел — закроем с чистой совестью. Нет — найди мне, как он оказался за рулём.', '[{"q": "Кто мне поможет?", "a": "— Сеитова. Следы, вещдоки — это к ней. Абишев на картотеках сидит, адресное бюро, узел связи, электросети — всё через него. Кан в морге. Ну и Бейсенов, доцент. Он у нас на этой неделе. Все здесь, в здании. Иди."}, {"q": "Что не так с этим «угаром»?", "a": "— А может, и ничего. *(пауза)* Только вскрытия не было. А мне отказной на подпись несут. Начни с морга, Кан бумагу ждёт. И на дачу съезди. Пока снегом всё не замело."}]'::jsonb, false, false, false, (select portrait_url from characters where name = 'Азамат Нурланович' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url, specialization) values ('d3ddcd6d-4093-5464-970c-de4ad3cb9af1', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Гульнара Сеитова', 'Криминалист ЭКО', 'Гульнара Сеитова, эксперт-криминалист ЭКО ГУВД. Свитер под белым халатом, волосы в узел.
Сеитова не поднимает головы от кальки.
— Что смотреть? Давайте конкретно.', '[{"q": "Что вы можете сделать по этому делу?", "a": "— Осмотр. Трасология, следы рук. Сравнение предметов. Купюры по номерам тоже, если будет с чем сравнивать. Если картотеку не поднимать — результат в тот же день. Картотека у Абишева."}, {"q": "Как по-вашему, это несчастный случай?", "a": "— Я говорю по предмету. Привезёте предмет — скажу, что на нём есть. А случай это или нет, решает следствие."}]'::jsonb, '{"b4e6a60f-b233-543e-b3b1-ae0a1427b6a1": "Сеитова раскладывает кальку на капоте служебного «уазика».\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер. Протектор глубокий, на каблуке косой порез, около сантиметра. Следы под тонким слоем снега. Снег, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часу.\nВторой: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти. Оставлены раньше, засветло, пока грязь была мягкая.\nИ борозды. Две, параллельные, со стороны водительской двери. Тело несли, ноги волочились. Чьи следы — не скажу. Размер скажу.", "46e78eb0-d057-5e5d-8a00-81457f8f3d20": "Сеитова не поднимает головы от стола.\n— Три тысячи. Тридцать купюр по сто. Сверила с ксерокопиями: серия, номер. У двух купюр надрыв на краю, на копии он тоже виден. Все тридцать есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — это не ко мне.", "00b31a8e-e1ee-5474-a323-177b43b153d3": "Сеитова снимает перчатки.\n— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам. Совпали все шесть.\nМужские следы у гаража дачи оставлены этими ботинками. Кто был в ботинках — вопрос не ко мне.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "Сеитова кладёт стопку протоколов рядом с листами ксерокопий.\n— Доллары из мешка с рисом. Пересчитала при понятых, номера переписала, сверила с копиями Ахметова лист за листом. Каждая купюра из тайника есть в копиях выкупа. Лишних нет. Чужих нет. Банковские резинки описаны. Рис описан отдельно.", "4f67be3f-f5f7-5ab5-bb69-611053df3042": "Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\nСеитова раскладывает купюры рядом с листами ксерокопий.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». Сверила номера. Все пять есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесла в протокол. Больше по конверту ничего.", "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду. Плату оставляет сохнуть на батарее. Наутро ставит новую батарейку.\n— Включился. Последнее принятое сообщение в памяти: четверг, двадцать первое, семнадцать тридцать пять. Позже ничего. В воде аппарат не принимает. Что на него слали после — это у оператора, к Абишеву. Калитку я сфотографировала. Выводов по ней не делаю.", "60950128-af31-513e-b8de-bb87b02332cc": "Сеитова раскладывает кальки.\n— Обувь. Нуртазин: форменные ботинки, сорок третий, протектор другого рисунка. Ахметов: сорок третий. Изъяла у него всё, что есть. Импортные туфли — подошва гладкая, кожаная. Зимние ботинки — протектор другой, пореза нет. Жумабаева: тридцать седьмой. Мужские следы у гаража ни одна из этих пар не оставила. Пары с порезом на каблуке среди того, что принесли, нет.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nСеитова кладёт пять купюр рядом с листами ксерокопий. Ведёт линейкой по строчкам.\n— Все пять есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "Сеитова кладёт рядом две кальки.\n— Дактокарта Бекенова. Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев по ГАИ: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела всё в одну бумагу.", "43eaf70c-177d-516a-9ab2-7aecc9633e33": "Сеитова возвращается со стоянки Медеуского РОВД. Брюки мокрые по колено.\n— Раз не угар, смотреть надо машину. Осмотрела. В колёсных арках жёлтая глина, плотная, налипла слоем. Такая бывает на немощёных улицах частного сектора. В Горном Гиганте, например, такие улицы. На Кок-Тобе к даче асфальт и щебень, там такую не наберёшь. Руль: ни одного отпечатка. Ни чужого, ни хозяйского. Последним машину вёл человек в перчатках. Кто — это не ко мне. Привезёте образец грунта — сравню.", "a9b47e33-f5b4-57b9-9e16-1e41c38e7834": "Сеитова трёт сажу между пальцами, нюхает.\n— Свежая. Мотор работал часа три, не меньше, на холостых, при закрытых воротах. Бак, говорите, сухой? Сходится.\n(вытирает руку платком)\nТолько копоть не скажет, был ли за рулём живой человек. Это вопрос к Кану, не ко мне."}'::jsonb, '[{"id": "R03", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "Сеитова раскладывает кальку на капоте служебного «уазика».\n— Два типа следов. Первый: мужская зимняя обувь, сорок третий размер. Протектор глубокий, на каблуке косой порез, около сантиметра. Следы под тонким слоем снега. Снег, по метеостанции, пошёл около часа ночи на воскресенье. Значит, следы ночные, до часу.\nВторой: женская обувь, тридцать седьмой. Эти под подмёрзшей коркой слякоти. Оставлены раньше, засветло, пока грязь была мягкая.\nИ борозды. Две, параллельные, со стороны водительской двери. Тело несли, ноги волочились. Чьи следы — не скажу. Размер скажу.", "grants": ["60950128-af31-513e-b8de-bb87b02332cc"]}, {"id": "R24", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "Сеитова не поднимает головы от стола.\n— Три тысячи. Тридцать купюр по сто. Сверила с ксерокопиями: серия, номер. У двух купюр надрыв на краю, на копии он тоже виден. Все тридцать есть в копиях выкупа. Совпадение полное. Протокол сравнения подпишу сегодня. Как они попали к нему за подкладку — это не ко мне.", "grants": ["d91852b9-daca-5340-80c9-a13cffe680cc"]}, {"id": "R27", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": ["60950128-af31-513e-b8de-bb87b02332cc"], "text": "Сеитова снимает перчатки.\n— Сорок третий. Протектор тот же. Порез на каблуке косой, около сантиметра, края совпадают со слепком у гаража. Ботинки мыли, но в шве у подошвы грязь осталась, на экспертизу хватит. Подошву сравнила с калькой по шести точкам. Совпали все шесть.\nМужские следы у гаража дачи оставлены этими ботинками. Кто был в ботинках — вопрос не ко мне.", "grants": ["6fc41a46-a0eb-5890-9b26-3b19bcef490d"]}, {"id": "R28", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042"], "text": "Сеитова кладёт стопку протоколов рядом с листами ксерокопий.\n— Доллары из мешка с рисом. Пересчитала при понятых, номера переписала, сверила с копиями Ахметова лист за листом. Каждая купюра из тайника есть в копиях выкупа. Лишних нет. Чужих нет. Банковские резинки описаны. Рис описан отдельно.", "grants": ["107fcb2c-e909-5f81-bba4-d218265227c5"]}, {"id": "R30", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": ["5cdb3307-fe10-53c5-a365-6998256b7d7a", "f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Вы кладёте рядом с конвертом «на похороны» показания Шнайдер: тот, кто принёс конверт, в субботу вечером был у дома Шмидтов.\nСеитова раскладывает купюры рядом с листами ксерокопий.\n— Конверт от матери покойного. Пять купюр по сто, новые, «с маленькой головой». Сверила номера. Все пять есть в копиях выкупа. Совпадение полное. Надпись карандашом «От Фархада — на похороны» внесла в протокол. Больше по конверту ничего.", "grants": ["26a10711-a53c-5105-9ed4-190697869496"]}, {"id": "R47", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Сеитова вскрывает корпус пейджера над лотком, сливает мутную воду. Плату оставляет сохнуть на батарее. Наутро ставит новую батарейку.\n— Включился. Последнее принятое сообщение в памяти: четверг, двадцать первое, семнадцать тридцать пять. Позже ничего. В воде аппарат не принимает. Что на него слали после — это у оператора, к Абишеву. Калитку я сфотографировала. Выводов по ней не делаю.", "grants": ["7ada2011-2720-5b69-8a9c-9291fdad70e9"]}, {"id": "R50", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Сеитова раскладывает кальки.\n— Обувь. Нуртазин: форменные ботинки, сорок третий, протектор другого рисунка. Ахметов: сорок третий. Изъяла у него всё, что есть. Импортные туфли — подошва гладкая, кожаная. Зимние ботинки — протектор другой, пореза нет. Жумабаева: тридцать седьмой. Мужские следы у гаража ни одна из этих пар не оставила. Пары с порезом на каблуке среди того, что принесли, нет.", "grants": ["7a9bdd9a-4323-5342-a3bd-24301a6d6e88"]}, {"id": "R59", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": ["4f67be3f-f5f7-5ab5-bb69-611053df3042", "27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "Вы приносите Сеитовой конверт «на похороны» и напоминаете: пальцы того, кто его принёс, сняты с люка в подвале Шмидтов.\nСеитова кладёт пять купюр рядом с листами ксерокопий. Ведёт линейкой по строчкам.\n— Все пять есть в копиях выкупа. Серия, номер — совпадение полное. Протокол сравнения подпишу сегодня.", "grants": ["26a10711-a53c-5105-9ed4-190697869496"]}, {"id": "R60", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Сеитова кладёт рядом две кальки.\n— Дактокарта Бекенова. Второй набор с крышки люка — его, по восьми признакам. Ахметова откатала тоже, он пришёл сам: с люком не совпадает. Кан смотрел кисти у обоих — свежих повреждений нет. Кровь у Бекенова — вторая группа, справка Кана. Абишев по ГАИ: водительского удостоверения и машины у Бекенова нет, говорит, что водить умеет. Свела всё в одну бумагу.", "grants": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"]}, {"id": "R64", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Сеитова возвращается со стоянки Медеуского РОВД. Брюки мокрые по колено.\n— Раз не угар, смотреть надо машину. Осмотрела. В колёсных арках жёлтая глина, плотная, налипла слоем. Такая бывает на немощёных улицах частного сектора. В Горном Гиганте, например, такие улицы. На Кок-Тобе к даче асфальт и щебень, там такую не наберёшь. Руль: ни одного отпечатка. Ни чужого, ни хозяйского. Последним машину вёл человек в перчатках. Кто — это не ко мне. Привезёте образец грунта — сравню.", "grants": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"]}, {"id": "R67", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "Сеитова трёт сажу между пальцами, нюхает.\n— Свежая. Мотор работал часа три, не меньше, на холостых, при закрытых воротах. Бак, говорите, сухой? Сходится.\n(вытирает руку платком)\nТолько копоть не скажет, был ли за рулём живой человек. Это вопрос к Кану, не ко мне.", "grants": []}]'::jsonb, null, true, false, true, (select portrait_url from characters where name ilike '%Сеитова%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1), 'Криминалист ЭКО');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url, specialization) values ('14e9bc6d-22f0-5005-b51c-e0678d8fa225', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Ринат Абишев', 'Оператор ИВЦ ГУВД', 'Ринат Абишев, оператор ИВЦ ГУВД. Картотечные ящики до потолка. На столе кружка остывшего чая.
— С запросом? Давайте. Только сразу скажу: всё по бумаге и не раньше чем через день. Ну, так у нас.', '[{"q": "Что вы можете проверить?", "a": "— Ну, судимости. Дактокарты. Адресное бюро, машины через ГАИ. Могу написать запрос на АТС, в пейджинговую, в электросети. Всё письменно, с подписью, и всё через день. Компьютер у нас, вот, один. И тот в бухгалтерии."}, {"q": "Что ещё имеет смысл проверить?", "a": "— Если похищение и был дом, где держали… Ну, тогда проверяйте всех, кто в тот вечер чем-то подтверждает, где был. Свет, телефон, смены. Свет я могу поднять отдельно по каждому району, хоть по улице. Скажите только какую. Электросети, они всё пишут: где отключали, где нет.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931", "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"q": "Как убийца ночью спустился с Кок-Тобе, если машину оставил в гараже?", "a": "— Пешком. А внизу частника остановил. Ну а как ещё. Частника вы не найдёте: они нигде не записываются. В субботу вечером по городу каждый второй с машиной подрабатывает. Это не след. Ищите то, что где-то записано.", "requires": ["3772cdd6-1fe9-52d0-a268-3f82441220c7"]}]'::jsonb, '{"1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Абишев берёт пейджер двумя пальцами. С него капает.\n— Ну, этот своё отработал. А номер на крышке есть. Позвонил в пейджинговую, девочки там нормальные, журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали. Из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз. И от матери. В офисе говорят: не перезвонил ни разу.\nА прочитал он или нет — этого никто не скажет. Пейджер в одну сторону работает: оператор отправил, и всё. Выводы уж вы сами.", "43eaf70c-177d-516a-9ab2-7aecc9633e33": "Абишев листает протокол РОВД.\n— Отключение света, значит. А было ли оно, РОВД проверять не стал. Ну ладно. Написал запрос диспетчеру районных электросетей по Кок-Тобе. Потом сам съездил: без печати бумагу не отдают. Вот. В субботу с девятнадцати ноль-ноль до двух ночи район Кок-Тобе обесточен. По графику.\nПро другие районы я не спрашивал: там на каждый район отдельная бумага. Так что света на даче не было. Тут РОВД прав.", "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba": "Абишев выслушивает. Стул под ним скрипит.\n— Пальцы на керосиновой лампе, в доме в Горном Гиганте. А сам он, говорит, сидел при свечке в «Орбите». Понял. Я ведь тогда только Кок-Тобе запрашивал. Ладно, пишу отдельно по «Орбите». Сразу за пятницу и за субботу, чтобы второй раз не ездить.\nЧерез день на столе бумага с печатью.\n— Вот. Ни в пятницу, ни в субботу в «Орбите» не отключали. Ни по графику, ни аварийно. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Это справка. Выводы — ваши.", "e4e94374-000e-52e3-bb26-9bec42b1c55b": "Абишев переписывает цифры с АОН на сигаретную пачку.\n— Суббота, пятнадцать тридцать. Хорошо, что у неё АОН на девяносто девять номеров. Был бы на двадцать — за два дня соболезнований этот бы уже вытеснило. По первым цифрам — частный сектор под горами. Ждите.\nЧерез час возвращается с листком.\n— Значит, так. Телефон зарегистрирован на Шмидта Г. Выбыл в ФРГ, на постоянное. Адрес — частный сектор в Горном Гиганте. Участковый тамошний говорит: дом пустой, продаётся по доверенности. А телефон не отключён. Выходит, звонили из пустого дома. На кого доверенность — это к нотариусу. А там неделя, не меньше.", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e": "— Номер, который ваш финансист с АОН запомнил? — Абишев кивает. — Бухгалтеры, они цифры помнят. Пробил через адресное бюро. Шмидт Г., выбыл в ФРГ на постоянное жительство. Частный сектор в Горном Гиганте. Участковый говорит: дом пустой, продаётся по доверенности. На кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу звонили.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "Абишев трёт глаза. Ночь не спал.\n— Пальцы с люка и с лампы. Гульнара сняла чисто, на копоти хорошо отпечаталось. Сравнивал вручную, по картотеке, всю ночь. Начал с тех, кто у вас в деле есть и на кого есть дактокарта.\nЕсть совпадение. Мамаджанов Фархад. Судим в девяносто четвёртом, таможенное дело.\nВторой набор с люка в картотеке не значится. Человек несудимый, на таких карточек нет.\nИ вот ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Это я так, к сведению.", "be5c249c-d25f-5239-865f-5aef2088bc61": "Абишев вертит в руках пейджер охранника.\n— Логику понял. Пустой дом знали, и четверги знали. Пустой дом — это бумаги, нотариус. А что хозяин по четвергам без шофёра ездит — это люди. Это знали на базе. Сообщения он стёр. Только у пейджинговой свой журнал: что им диктуют, то они и записывают.\nКладёт перед вами листок, переписанный от руки.\n— Четверг, двадцать первое. Шестнадцать тридцать. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.» — оператор не спрашивает. В журнале этого нет.", "f725c4c5-f254-5c01-b718-3531a957102a": "— Подождите. Соседка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил: сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» я не проверял, я Кок-Тобе проверял. Сейчас.\nЗвонит. Ждёт. Записывает.\n— Диспетчер говорит: в «Орбите» ни в пятницу, ни в субботу отключений не было. Свет был. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра. Ну а знать вы это можете уже сегодня.", "b229ab87-5e5b-5f61-8a7b-18c17718e4cf": "Абишев рисует таблицу на обороте старой ориентировки.\n— Даты свёл, раз все бумаги у меня. Чайхана, где охраннику долг списали, — девятое, суббота. За две недели до похищения. «Волга» у ворот базы — четырнадцатое, за неделю. «Месяц тебе, или сядешь» — шестнадцатое, за пять дней. Похищение — двадцать первое. Получается, к шестнадцатому наводка уже куплена и ворота высмотрены. Кто там потом на кого кричал, для плана уже значения не имело. Это не вывод. Это календарь."}'::jsonb, '[{"id": "R02", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": [], "text": "Абишев берёт пейджер двумя пальцами. С него капает.\n— Ну, этот своё отработал. А номер на крышке есть. Позвонил в пейджинговую, девочки там нормальные, журнал подняли. Значит, так. С вечера четверга до субботы на этот номер диктовали. Из офиса — «СРОЧНО ПЕРЕЗВОНИ», несколько раз. И от матери. В офисе говорят: не перезвонил ни разу.\nА прочитал он или нет — этого никто не скажет. Пейджер в одну сторону работает: оператор отправил, и всё. Выводы уж вы сами.", "grants": ["7ada2011-2720-5b69-8a9c-9291fdad70e9"]}, {"id": "R10", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Абишев листает протокол РОВД.\n— Отключение света, значит. А было ли оно, РОВД проверять не стал. Ну ладно. Написал запрос диспетчеру районных электросетей по Кок-Тобе. Потом сам съездил: без печати бумагу не отдают. Вот. В субботу с девятнадцати ноль-ноль до двух ночи район Кок-Тобе обесточен. По графику.\nПро другие районы я не спрашивал: там на каждый район отдельная бумага. Так что света на даче не было. Тут РОВД прав.", "grants": ["9eedb06d-09c9-5fa6-b91f-46d7753f78b4"]}, {"id": "R11", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "Абишев выслушивает. Стул под ним скрипит.\n— Пальцы на керосиновой лампе, в доме в Горном Гиганте. А сам он, говорит, сидел при свечке в «Орбите». Понял. Я ведь тогда только Кок-Тобе запрашивал. Ладно, пишу отдельно по «Орбите». Сразу за пятницу и за субботу, чтобы второй раз не ездить.\nЧерез день на столе бумага с печатью.\n— Вот. Ни в пятницу, ни в субботу в «Орбите» не отключали. Ни по графику, ни аварийно. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Это справка. Выводы — ваши.", "grants": ["64b699fc-69d6-5bc3-ab81-b5a48df561bd"]}, {"id": "R12", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": [], "text": "Абишев переписывает цифры с АОН на сигаретную пачку.\n— Суббота, пятнадцать тридцать. Хорошо, что у неё АОН на девяносто девять номеров. Был бы на двадцать — за два дня соболезнований этот бы уже вытеснило. По первым цифрам — частный сектор под горами. Ждите.\nЧерез час возвращается с листком.\n— Значит, так. Телефон зарегистрирован на Шмидта Г. Выбыл в ФРГ, на постоянное. Адрес — частный сектор в Горном Гиганте. Участковый тамошний говорит: дом пустой, продаётся по доверенности. А телефон не отключён. Выходит, звонили из пустого дома. На кого доверенность — это к нотариусу. А там неделя, не меньше.", "grants": ["f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"id": "R13", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Номер, который ваш финансист с АОН запомнил? — Абишев кивает. — Бухгалтеры, они цифры помнят. Пробил через адресное бюро. Шмидт Г., выбыл в ФРГ на постоянное жительство. Частный сектор в Горном Гиганте. Участковый говорит: дом пустой, продаётся по доверенности. На кого — не знает, это к нотариусу. Телефон в доме не отключён. И с него, выходит, в субботу звонили.", "grants": ["f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba"]}, {"id": "R17", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "Абишев трёт глаза. Ночь не спал.\n— Пальцы с люка и с лампы. Гульнара сняла чисто, на копоти хорошо отпечаталось. Сравнивал вручную, по картотеке, всю ночь. Начал с тех, кто у вас в деле есть и на кого есть дактокарта.\nЕсть совпадение. Мамаджанов Фархад. Судим в девяносто четвёртом, таможенное дело.\nВторой набор с люка в картотеке не значится. Человек несудимый, на таких карточек нет.\nИ вот ещё. В учётном деле лежит медкарта из колонии. Группа крови — вторая. Это я так, к сведению.", "grants": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"]}, {"id": "R20", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Абишев вертит в руках пейджер охранника.\n— Логику понял. Пустой дом знали, и четверги знали. Пустой дом — это бумаги, нотариус. А что хозяин по четвергам без шофёра ездит — это люди. Это знали на базе. Сообщения он стёр. Только у пейджинговой свой журнал: что им диктуют, то они и записывают.\nКладёт перед вами листок, переписанный от руки.\n— Четверг, двадцать первое. Шестнадцать тридцать. Абонент Нуртазин. Текст: «ЧЕТВЕРГ В СИЛЕ? Ф.». Кто такой «Ф.» — оператор не спрашивает. В журнале этого нет.", "grants": ["c50332f2-fb14-5cff-9ea2-9581024ac2e3"]}, {"id": "R38", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Мамаджанов? Он у нас есть. Судим в девяносто четвёртом, таможня, дактокарта с тех пор лежит. — Абишев тянет с полки ящик картотеки. — Сравнивал вручную, полночи. Пальцы с крышки люка и с керосиновой лампы — его, Гульнара подтвердит. Второй набор с люка в картотеке не значится: человек несудимый. И раз уж я в его деле сидел: медкарта колонии, группа крови вторая. Это так, к сведению. В медицине я не понимаю.", "grants": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"]}, {"id": "R48", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Подождите. Соседка видела его «Волгу» у дома Шмидтов в субботу вечером? А он вам говорил: сидел в «Орбите» при свечке. — Абишев роется в бумагах. — «Орбиту» я не проверял, я Кок-Тобе проверял. Сейчас.\nЗвонит. Ждёт. Записывает.\n— Диспетчер говорит: в «Орбите» ни в пятницу, ни в субботу отключений не было. Свет был. В субботу с семи вечера отключали только Кок-Тобе и Горный Гигант. Бумагу пришлют завтра. Ну а знать вы это можете уже сегодня.", "grants": ["64b699fc-69d6-5bc3-ab81-b5a48df561bd"]}, {"id": "R51", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": [], "text": "Абишев тянется за сигаретами.\n— «Волга» с одной фарой? По вашему кругу запросил ИЦ и ГАИ. Мамаджанов Ф. — ГАЗ-24, «Волга», белая. Что у неё с фарами, ГАИ не пишет, в карточке такого нет. Ахметов — ВАЗ-2109, белая. Попросил гаишников глянуть у офиса: фары целы, обе. Жумабаева — «Таврия», красная. Нуртазин — личной машины нет, ездит на служебном «уазике» агентства. Белых, значит, две. Дальше смотрите сами.", "grants": ["d8f33493-fc81-5e50-af40-37d9500040b6"]}, {"id": "R57", "on": "b229ab87-5e5b-5f61-8a7b-18c17718e4cf", "requires": ["0a295d5f-e115-5c89-a26a-5992761304a0", "c4c95f03-86b0-5820-b9f4-736453e2dbef"], "text": "Абишев рисует таблицу на обороте старой ориентировки.\n— Даты свёл, раз все бумаги у меня. Чайхана, где охраннику долг списали, — девятое, суббота. За две недели до похищения. «Волга» у ворот базы — четырнадцатое, за неделю. «Месяц тебе, или сядешь» — шестнадцатое, за пять дней. Похищение — двадцать первое. Получается, к шестнадцатому наводка уже куплена и ворота высмотрены. Кто там потом на кого кричал, для плана уже значения не имело. Это не вывод. Это календарь.", "grants": ["06da149b-c92c-54fa-a5f5-b78ff87dbc92"]}, {"id": "R58", "on": "be5c249c-d25f-5239-865f-5aef2088bc61", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "c2c5ba62-e24e-523f-93bc-d8909b28e717"], "text": "Абишев откладывает пейджер охранника.\n— Подвал в пустом доме за один вечер не готовят. Матрас, верёвки, ведро. Значит, ждали заранее, и ждали именно в четверг. Кто-то знал, что по четвергам хозяин едет без шофёра. А это знали на базе. Ну вот. Журнал пейджинговой за двадцать первое: шестнадцать тридцать, абонент Нуртазин, текст «ЧЕТВЕРГ В СИЛЕ? Ф.». Это всё, что у них есть. Кто подписался «Ф.», в журнале не пишут.", "grants": ["c50332f2-fb14-5cff-9ea2-9581024ac2e3"]}, {"id": "R61", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"], "text": "— Высокий молодой парень вышел из «Волги» вместе с Мамаджановым? Значит, смотрим, кто у Мамаджанова в городе из молодых. — Абишев снимает с полки учётное дело девяносто четвёртого года, листает анкету. — Графа «родственники»: двоюродная сестра, Бекенова, Талгарский район. Дальше адресное бюро. По городу прописан один Бекенов оттуда. Олжас, двадцать два года. Временная прописка: общежитие у Зелёного базара, комната четыреста двенадцать. Племянник, выходит. Это фамилия и адрес. Остальное не ко мне.", "grants": ["6a92b637-cb0c-5bf4-8495-f503839bf08c"]}, {"id": "R62", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": ["27ae146a-a05c-5e7a-84a1-899c35e883e4"], "text": "— Курьер на остановке: высокий, молодой, куртка, ушанка. И пальцы Мамаджанова в том подвале. Ну, значит, смотрим, кто у Мамаджанова в городе из молодых. — Абишев снова достаёт учётное дело девяносто четвёртого года. — Анкета, графа «родственники»: двоюродная сестра, Бекенова, Талгарский район. Адресное бюро: в городе временно прописан Бекенов Олжас, двадцать два года, оттуда же. Общежитие у Зелёного базара, комната четыреста двенадцать. Вот справка.", "grants": ["6a92b637-cb0c-5bf4-8495-f503839bf08c"]}]'::jsonb, null, true, false, true, (select portrait_url from characters where name ilike '%Абишев%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1), 'Оператор ИВЦ ГУВД');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url, specialization) values ('a6c62ec0-5ff9-53a5-b9a2-20898741074b', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Юрий Николаевич Кан', 'Судмедэксперт', 'Юрий Николаевич Кан, судмедэксперт. Тридцать лет в морге. Нарукавники, очки на цепочке.
Кан моет руки. Не оборачивается.
— Давайте, что у вас. Только побыстрее: у меня их сегодня шестеро.', '[{"q": "В гараже можно угореть?", "a": "— Можно. Каждую зиму привозят. Свет отключили, человек сел в машину погреться, а гараж закрыт. Ну вот. Только мне направление нужно. Без бумаги я вскрывать не буду."}, {"q": "Насколько надёжна группа крови как улика?", "a": "— Группа крови исключает, но не называет. Вторая — у каждого третьего в городе. Не совпала — значит, не он. Совпала — ищите дальше. Вот и всё.", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"]}]'::jsonb, '{"e34a96b0-5d0e-5414-9ef3-048071ef84ed": "Кан снимает очки. Протирает полой халата. Долго.\n— Не угорел он, голубчик. Угоревший — он розовый. А этот синий, одутловатый, в глазах точечные кровоизлияния. Удушение, шею сдавили. В машину его посадили уже мёртвым. Смерть — суббота, около двадцати двух. Ну, час туда-сюда.\nДальше. На запястьях слабые следы: связывали поверх рукавов. Щетина дня два, обезвоживание, голодал. Двое суток он где-то был. И не по своей воле.\nИ вот ещё. Под ногтями кровь. У него первая группа. А под ногтями вторая. Чья — это уже не ко мне.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "Кабинет. Двое понятых. Кан просит задержанного положить левую руку на стол и сам разматывает бинт. Виток за витком.\n— Ожога нет. Ни пузыря, ни пятна.\nБерёт лупу.\n— Царапины. Три, параллельные, края дугой. Это ногти, человеческие. От животного следы другие, я их видел достаточно. Давность — четверо-шестеро суток, заживают. Вечеру субботы не противоречит.\nТеперь второе. По медкарте колонии группа вторая. Под ногтями покойного тоже вторая. Только вторая — у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины отдельно, группа отдельно. Я описываю, что вижу. Складывать будете вы.", "54bf13bc-3525-5eec-9441-609d8ee21f59": "Кан надевает очки, читает с листа.\n— Таблица. Запросил медкарты и учётные дела на всех, кто у вас в деле с фамилией и адресом. Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела МВД, он у нас служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — это не отпечаток пальца. Исключить человека она может. Назвать — нет.", "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c": "Валентина Петровна вспомнила: в воскресенье рука у него была расцарапана. «Собака на базаре».\nКан кивает. В кабинете, при понятых, разматывает бинт на кисти задержанного.\n— Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает: от собаки покусы, когти, след другой. Давность — четверо-шестеро суток, заживают. С вечером субботы совместимо. Группа у него по медкарте колонии вторая. Под ногтями покойного тоже вторая. Я описываю кисть. Выводы делайте сами.", "b177dd97-7391-5f5e-8308-72a1073516c2": "Кан дописывает строку в свою таблицу.\n— Бекенова, задержанного, привели с утра. Кровь взял: вторая группа. Кисти посмотрел у него и, для порядка, у Ахметова. Тот пришёл сам, рукава засучил без разговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат по ГАИ добавил: прав и машины у Бекенова нет. Водить, говорит, умеет. Вот. Я описываю. Складываете вы."}'::jsonb, '[{"id": "R01", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Кан снимает очки. Протирает полой халата. Долго.\n— Не угорел он, голубчик. Угоревший — он розовый. А этот синий, одутловатый, в глазах точечные кровоизлияния. Удушение, шею сдавили. В машину его посадили уже мёртвым. Смерть — суббота, около двадцати двух. Ну, час туда-сюда.\nДальше. На запястьях слабые следы: связывали поверх рукавов. Щетина дня два, обезвоживание, голодал. Двое суток он где-то был. И не по своей воле.\nИ вот ещё. Под ногтями кровь. У него первая группа. А под ногтями вторая. Чья — это уже не ко мне.", "grants": ["54bf13bc-3525-5eec-9441-609d8ee21f59"]}, {"id": "R29", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Кабинет. Двое понятых. Кан просит задержанного положить левую руку на стол и сам разматывает бинт. Виток за витком.\n— Ожога нет. Ни пузыря, ни пятна.\nБерёт лупу.\n— Царапины. Три, параллельные, края дугой. Это ногти, человеческие. От животного следы другие, я их видел достаточно. Давность — четверо-шестеро суток, заживают. Вечеру субботы не противоречит.\nТеперь второе. По медкарте колонии группа вторая. Под ногтями покойного тоже вторая. Только вторая — у каждого третьего в городе, сама по себе она ничего не доказывает. Царапины отдельно, группа отдельно. Я описываю, что вижу. Складывать будете вы.", "grants": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"]}, {"id": "R49", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Кан надевает очки, читает с листа.\n— Таблица. Запросил медкарты и учётные дела на всех, кто у вас в деле с фамилией и адресом. Мамаджанов — вторая, по медкарте колонии. Ахметов — вторая. Нуртазин — первая, из личного дела МВД, он у нас служил. Жумабаева — третья. Под ногтями — вторая. Двоим подходит, двоим нет. Группа крови — это не отпечаток пальца. Исключить человека она может. Назвать — нет.", "grants": ["b177dd97-7391-5f5e-8308-72a1073516c2"]}, {"id": "R52", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"], "text": "Валентина Петровна вспомнила: в воскресенье рука у него была расцарапана. «Собака на базаре».\nКан кивает. В кабинете, при понятых, разматывает бинт на кисти задержанного.\n— Ожога под бинтом нет. Царапины: три, параллельные, края дугой. Ногти, человеческие. От собаки так не бывает: от собаки покусы, когти, след другой. Давность — четверо-шестеро суток, заживают. С вечером субботы совместимо. Группа у него по медкарте колонии вторая. Под ногтями покойного тоже вторая. Я описываю кисть. Выводы делайте сами.", "grants": ["7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"]}, {"id": "R53", "on": "b177dd97-7391-5f5e-8308-72a1073516c2", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"], "text": "Кан дописывает строку в свою таблицу.\n— Бекенова, задержанного, привели с утра. Кровь взял: вторая группа. Кисти посмотрел у него и, для порядка, у Ахметова. Тот пришёл сам, рукава засучил без разговоров. Свежих повреждений нет ни у того, ни у другого. Гульнара сверила дактокарту Бекенова со вторым набором с люка — его. С пальцами Ахметова тот набор не совпал. Ринат по ГАИ добавил: прав и машины у Бекенова нет. Водить, говорит, умеет. Вот. Я описываю. Складываете вы.", "grants": ["9281d556-d163-5537-a0e2-e4cd2e635ba5"]}]'::jsonb, null, true, false, true, (select portrait_url from characters where name ilike '%Кан' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1), 'Судмедэксперт');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url, specialization) values ('11b90ca2-3c48-573f-95ac-041cf0635f90', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '006a31f4-baeb-5b53-9a87-6a397ba18362', 'Аскар Бейсенов', 'Криминолог, доцент высшей школы МВД', 'Аскар Бейсенов, криминолог, доцент Высшей школы МВД. Пиджак, кожаный портфель, отточенный карандаш.
Бейсенов постукивает карандашом по блокноту.
— Давайте с фактов. Предположения потом.', '[{"q": "Чем вы можете помочь?", "a": "— Типологией. Я могу сказать, как обычно ведут себя люди в такой ситуации и кто в неё, как правило, попадает. А кто попал в вашу — это уже следствие. Не наука."}, {"q": "Почему семья молчала?", "a": "— К сожалению, это типично. Милиции у нас не доверяют, и давно. Семья боится не столько похитителей, сколько того, что милиция их спугнёт. И учтите: молчание свидетеля — ещё не соучастие.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}]'::jsonb, '{"34e1077a-bcc2-53ac-90e8-702d023d03c7": "Бейсенов долго смотрит фототаблицу и схему следов. Постукивает карандашом.\n— Скажу, как это выглядит с точки зрения криминологии. Заложника, за которого получен выкуп, обычно отпускают. Мёртвый заложник похитителю ни к чему, это лишний риск. После выкупа убивают, как правило, в одном случае: похититель боится, что его опознают. То есть жертва его знала.\nДальше. Инсценировку делал человек, который знал дачу, знал привычки покойного и рассчитывал, что семья промолчит. Это не случайные люди. Это круг: друзья семьи, партнёры, бывшие супруги, охрана.\nИмён я не называю. Это закономерность, не больше.", "0a295d5f-e115-5c89-a26a-5992761304a0": "Бейсенов раскладывает на столе четыре листка с показаниями. По датам, слева направо. Карандашом — по каждому.\n— Давайте по хронологии. Девятое ноября, суббота: разговор в чайхане. Наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой стоит у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста, «месяц тебе, или сядешь». Двадцать первое: похищение.\nПодготовка началась за неделю до того, как у финансиста появилась причина. А как правило, бывает наоборот: сначала мотив, потом план. Имён я не называю. Это порядок дат."}'::jsonb, '[{"id": "R23", "on": "34e1077a-bcc2-53ac-90e8-702d023d03c7", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59", "b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Бейсенов долго смотрит фототаблицу и схему следов. Постукивает карандашом.\n— Скажу, как это выглядит с точки зрения криминологии. Заложника, за которого получен выкуп, обычно отпускают. Мёртвый заложник похитителю ни к чему, это лишний риск. После выкупа убивают, как правило, в одном случае: похититель боится, что его опознают. То есть жертва его знала.\nДальше. Инсценировку делал человек, который знал дачу, знал привычки покойного и рассчитывал, что семья промолчит. Это не случайные люди. Это круг: друзья семьи, партнёры, бывшие супруги, охрана.\nИмён я не называю. Это закономерность, не больше.", "grants": ["3b4003bd-1d82-5ec7-b07b-4c54af3ac4c0"]}, {"id": "R56", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": ["c4c95f03-86b0-5820-b9f4-736453e2dbef", "b229ab87-5e5b-5f61-8a7b-18c17718e4cf"], "text": "Бейсенов раскладывает на столе четыре листка с показаниями. По датам, слева направо. Карандашом — по каждому.\n— Давайте по хронологии. Девятое ноября, суббота: разговор в чайхане. Наводчику предлагают списать долг за сведения о четвергах. Четырнадцатое, четверг: белая «Волга» с разбитой фарой стоит у ворот базы. Шестнадцатое, суббота: покойный уличает своего финансиста, «месяц тебе, или сядешь». Двадцать первое: похищение.\nПодготовка началась за неделю до того, как у финансиста появилась причина. А как правило, бывает наоборот: сначала мотив, потом план. Имён я не называю. Это порядок дат.", "grants": ["06da149b-c92c-54fa-a5f5-b78ff87dbc92"]}]'::jsonb, null, true, false, true, (select portrait_url from characters where name ilike '%Бейсенов%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1), 'Криминолог, доцент высшей школы МВД');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('54b23338-3cf2-5d0a-99c4-91c0de226522', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Виктор Гринько', 'Водитель Игоря с 1995 года, бывший таксист из автопарка', 'Виктор Гринько, 52 года, водитель покойного. Бывший таксист из автопарка.
Стоит у ворот дачи. Курит в кулак, на гараж не смотрит.
— Это я его нашёл. Ну... Что надо — покажу.', '[{"q": "Как вы его нашли?", "a": "— Валентина Петровна в воскресенье с утра звонит: Витя, съезди, проверь дачу. Ну, я поехал. В девять сорок был.\nВорота гаража закрыты. Тихо. Открываю — а он за рулём сидит.\nБак пустой. Мотор холодный, я рукой трогал. Ну и всё... Я к соседям, от них в милицию звонил. Больше ничего не трогал. Честно."}, {"q": "А в субботу вечером вы где были?", "a": "— Ну... (мнёт кепку) Таксовал. Частником, на своей «копейке». Я ж в автопарке таксовал, руки помнят.\nУ Сартакова платили — сами знаете сколько. Вот и катаю по вечерам.\nТолько Данияру не говорите. Он не любит, когда водитель налево ездит."}, {"q": "Какой он был, Игорь?", "a": "— Требовал много. Платил мало. Не бил, не орал... ну, почти.\nА так — не моё дело, какой он был. Моё дело — баранка."}]'::jsonb, '{"43eaf70c-177d-516a-9ab2-7aecc9633e33": "Виктор мнёт кепку. Смотрит не на протокол, а на гараж.\n— Угорел, написали... Ну, может, и угорел.\nЯ вам так скажу. По четвергам он меня в пять отпускал. Всегда. «Витя, свободен, я сам». И сюда, на дачу. Один. Это после развода повелось.\nДа все знали. Офис, на КПП ребята. Кто угодно.\n(пауза) И вот ещё. Неделю назад, тоже четверг. Выезжаю с базы — у ворот «Волга». Двадцать четвёртая, белая. Левая фара разбита, не горит.\nМужик за рулём сидит, курит. На ворота смотрит.\nНомер не запомнил, темно было. А фару запомнил. Я машины лучше людей помню.", "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1": "Виктор стоит у ворот гаража. Внутрь не заходит.\n— Я его полтора года возил. Каждый день.\nКроме четверга. В пять — «свободен, Витя». И сам за руль. И сюда, наверх. Один.\nПосле развода так стало. На базе все знали. На КПП ему шлагбаум заранее поднимали.\n(пауза) А ещё... В прошлый четверг у ворот базы «Волга» стояла. Белая, двадцать четвёртая. Левая фара разбита.\nМужик сидит, курит. На ворота смотрит.\nЯ тогда подумал — клиента ждёт. Ну, частник. А теперь не знаю, что и думать.", "a9b47e33-f5b4-57b9-9e16-1e41c38e7834": "Виктор смотрит на пятно, отворачивается.\n— Прогревать он любил, да. Минут пять, десять. Но во дворе! Ворота настежь. Он гаража боялся, говорил: душегубка.\nЧтобы он сам ворота закрыл и сидел... Нет. Не он это."}'::jsonb, '[{"id": "R04", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Виктор мнёт кепку. Смотрит не на протокол, а на гараж.\n— Угорел, написали... Ну, может, и угорел.\nЯ вам так скажу. По четвергам он меня в пять отпускал. Всегда. «Витя, свободен, я сам». И сюда, на дачу. Один. Это после развода повелось.\nДа все знали. Офис, на КПП ребята. Кто угодно.\n(пауза) И вот ещё. Неделю назад, тоже четверг. Выезжаю с базы — у ворот «Волга». Двадцать четвёртая, белая. Левая фара разбита, не горит.\nМужик за рулём сидит, курит. На ворота смотрит.\nНомер не запомнил, темно было. А фару запомнил. Я машины лучше людей помню.", "grants": ["c4c95f03-86b0-5820-b9f4-736453e2dbef"]}, {"id": "R05", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Виктор долго молчит. Кепку в руках не мнёт — держит.\n— Задушили, значит...\nНу тогда скажу. Я не стукач. Но раз такое дело.\nВ субботу, шестнадцатого. За пять дней до того четверга. Сижу в приёмной, дверь в кабинет неплотно закрыта.\nИгорь на Данияра орёт. Я его таким не слышал. Никогда.\n«Месяц тебе, или сядешь». Слово в слово.\nДанияр выходит — белый. Папку к груди прижал.\nА про что это — не знаю. Я в бумаги не лезу. Моё дело — баранка.", "grants": ["0a295d5f-e115-5c89-a26a-5992761304a0"]}, {"id": "R45", "on": "b4e6a60f-b233-543e-b3b1-ae0a1427b6a1", "requires": [], "text": "Виктор стоит у ворот гаража. Внутрь не заходит.\n— Я его полтора года возил. Каждый день.\nКроме четверга. В пять — «свободен, Витя». И сам за руль. И сюда, наверх. Один.\nПосле развода так стало. На базе все знали. На КПП ему шлагбаум заранее поднимали.\n(пауза) А ещё... В прошлый четверг у ворот базы «Волга» стояла. Белая, двадцать четвёртая. Левая фара разбита.\nМужик сидит, курит. На ворота смотрит.\nЯ тогда подумал — клиента ждёт. Ну, частник. А теперь не знаю, что и думать.", "grants": ["c4c95f03-86b0-5820-b9f4-736453e2dbef"]}, {"id": "R68", "on": "a9b47e33-f5b4-57b9-9e16-1e41c38e7834", "requires": [], "text": "Виктор смотрит на пятно, отворачивается.\n— Прогревать он любил, да. Минут пять, десять. Но во дворе! Ворота настежь. Он гаража боялся, говорил: душегубка.\nЧтобы он сам ворота закрыл и сидел... Нет. Не он это.", "grants": []}]'::jsonb, null, false, false, true, (select portrait_url from characters where name ilike '%Гринько%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('96e916c8-7fd0-5edc-a4fe-1a6aeda231bf', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '29196055-161c-5b4e-a38f-352cbf3e5032', 'Алия Сартакова (Жумабаева)', 'Бывшая жена Игоря, врач-анестезиолог городской больницы', 'Алия Жумабаева, 37 лет, бывшая жена. Анестезиолог городской больницы. Зарплату задерживают третий месяц.
Красная «Таврия» тормозит у ворот. Пуховик поверх халата: прямо с дежурства.
— Алия. Бывшая. Приехала посмотреть, что вы тут делаете с моим домом.', '[{"q": "Когда вы последний раз были на даче?", "a": "— С лета не была.\nЧто мне тут делать? На его машину любоваться? В гараже, который мой отец строил?"}, {"q": "Вы с ним ссорились?", "a": "— Ссорились. На прошлой неделе, у его матери. Я крикнула: «Чтоб ты сдох с этим домом». Валентина Петровна вам уже доложила. Или доложит.\nДачу строили на деньги от квартиры моих родителей. А оформил он её на себя.\n(пауза) Вот и весь мой мотив. Записывайте."}, {"q": "Как он, по-вашему, мог угореть?", "a": "— Легко. Котёл не чинил, грелся в машине. Всю жизнь.\nЯ ему десять лет говорила: угоришь. Как врач говорила."}, {"q": "Зачем вам была нужна папка с документами?", "a": "— Для иска. Адвокат сказал: без бумаг о приватизации даже разговаривать не о чем.\nЯ её не украла. Забрала.\nЭто мой дом. И будет домом моей дочери.", "requires": ["42ea83ef-f3ad-504f-99e0-da4ecb9fe57d"]}]'::jsonb, '{"60950128-af31-513e-b8de-bb87b02332cc": "Алия смотрит на снимок следа. Коротко смеётся. Зло.\n— Тридцать седьмой. Мой.\nЛадно. Была.\nВ пятницу. В три часа дня. Специально выбрала, когда он на работе.\nКлючи старые, на одной связке остались. Замки он так и не сменил. Жадность.\nЗабрала папку о приватизации. Для адвоката, для иска.\n(пауза) Гараж был пустой. Машины не было. Никого не было.\nА в субботу — с восьми вечера до восьми утра дежурство. В одиннадцать десять я давала наркоз, экстренная. Журнал дежурств, протокол с моей подписью.\nПроверяйте.\nЯ его хотела засудить. Не убить."}'::jsonb, '[{"id": "R06", "on": "60950128-af31-513e-b8de-bb87b02332cc", "requires": [], "text": "Алия смотрит на снимок следа. Коротко смеётся. Зло.\n— Тридцать седьмой. Мой.\nЛадно. Была.\nВ пятницу. В три часа дня. Специально выбрала, когда он на работе.\nКлючи старые, на одной связке остались. Замки он так и не сменил. Жадность.\nЗабрала папку о приватизации. Для адвоката, для иска.\n(пауза) Гараж был пустой. Машины не было. Никого не было.\nА в субботу — с восьми вечера до восьми утра дежурство. В одиннадцать десять я давала наркоз, экстренная. Журнал дежурств, протокол с моей подписью.\nПроверяйте.\nЯ его хотела засудить. Не убить.", "grants": ["42ea83ef-f3ad-504f-99e0-da4ecb9fe57d"]}]'::jsonb, array['54bf13bc-3525-5eec-9441-609d8ee21f59','7ada2011-2720-5b69-8a9c-9291fdad70e9']::uuid[], false, true, true, (select portrait_url from characters where name ilike 'Алия%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('0e8eb7cc-a947-5525-80eb-0978454d919b', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Валентина Петровна Сартакова', 'Мать Игоря, учительница литературы на пенсии', 'Валентина Петровна Сартакова, 66 лет. Учительница литературы на пенсии. Мать погибшего.
Встречает в прихожей. Чёрный платок, спина прямая, глаза сухие.
— Вы из ГУВД. Проходите. Только, пожалуйста… не при людях. Там на кухне люди.', '[{"q": "Когда вы последний раз говорили с сыном?", "a": "— В четверг. Утром, по телефону. Он сказал… Он уехал по делам. В Бишкек, я думаю, он туда часто ездил. Мы не волновались. Нет. Никаких звонков не было. — Поправляет платок. — А в воскресенье я послала Виктора на дачу. Потому что… ну, мать чувствует. Вот и всё. Мать чувствует."}, {"q": "Кто мог желать Игорю зла?", "a": "— Я не люблю наговаривать на людей. — Пауза. — Но вы всё равно узнаете. На прошлой неделе. Вот здесь, за этим столом. Его бывшая жена кричала: «Чтоб ты сдох с этим домом». Так и сказала. При мне. При девочке, видимо, нельзя. А при мне можно."}, {"q": "Кто такой Фархад?", "a": "— Фархад-ака? Он… двадцать лет как родной. Игорь у него начинал, совсем мальчишкой. Каждую пятницу у меня плов ел. Вот на этом стуле. — Пауза. — Потом у них были… разные годы. Не будем об этом. Но он пришёл. Многие не пришли. А он пришёл."}, {"q": "Почему вы не пошли в милицию?", "a": "— Потому что мне сказали: внучку больше не увидите. Вы бы пошли? Вы бы пошли, я вас спрашиваю? — Пауза. — Я не собрала. Сорок вместо шестидесяти. Сорок. Вот почему его… Из-за двадцати тысяч, которых у меня не было. — Голос становится ровным, учительским. — И ещё. Они знали про дачу. Про четверги. Про Дашу. Кто им это рассказал? Я знаю, кому был нужен этот дом.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}, {"q": "Какой шарф был у Игоря?", "a": "— Серый. Кашемировый, итальянский. Я его из Москвы привезла, ещё когда можно было ездить в Москву за шарфами. Он всю осень в нём ходил. Всю осень. — Поднимает глаза. — Вы его нашли. Где?", "requires": ["87af9a91-8540-5177-bdd6-3e156802fc75"]}, {"q": "Что это за конверт в серванте?", "a": "— Это? Фархад-ака вчера вечером принёс. На похороны.\n(достаёт конверт, протягивает)\nСмотрите, смотрите. Пятьсот долларов. Золотой человек. У самого ничего нет, а принёс.\nЯ ему говорю: не надо. А он: «Валя-апа, это не вам. Это Игорю».", "grants_evidence_id": "5cdb3307-fe10-53c5-a365-6998256b7d7a"}]'::jsonb, '{"e4e94374-000e-52e3-bb26-9bec42b1c55b": "Валентина Петровна смотрит на красные цифры АОН. Потом на свой блокнот.\n— Игорь поставил. Чтобы я знала, кто звонит. Ну вот. Знаю. — Садится, спинки стула не касается. — В четверг. Около девяти. Из автомата. Шестьдесят тысяч долларов. Пойдёте в милицию — Дашу не увидите. — Пауза. — Мы с Данияром собрали сорок. Больше не было. Не было больше.\nВ субботу, в половине четвёртого, ещё раз. Вот этот номер. Данияр рядом стоял, видел. Он отвёз деньги. Вернулся. И мы сидели. С половины восьмого до половины второго, здесь, у телефона. Ждали. — Нажимает кнопку, цифры гаснут. — Он так радовался этой коробочке. «Мама, теперь ты всё будешь знать».", "54bf13bc-3525-5eec-9441-609d8ee21f59": "Вы кладёте перед ней заключение Кана и пейджер из арыка. Говорите: молчание Дашу не защитит. Защитить её может только милиция.\nНа кухне перестают звенеть посудой.\n— Я тридцать лет учила детей говорить правду. Тридцать лет. А сама… — Долгая пауза. — Хорошо. Хорошо. Четверг, около девяти. Автомат. Шестьдесят тысяч, иначе внучку не увидим. Мы с Данияром собрали сорок. — Сбивается. — Суббота… половина четвёртого. Второй звонок, номер в АОН остался. Данияр отвёз деньги. Вернулся. С половины восьмого до половины второго был со мной. — Голос ломается. — Я молчала, чтобы уберечь Дашу. А вышло… как у плохой ученицы. Молчит, потому что не выучила.", "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44": "Валентина Петровна берёт пейджер. Смотрит на АОН. На блокнот, где цифры её почерком.\n— Его пейджер. В арыке, у ворот… Он не уезжал в Бишкек. — Пауза. — Это я придумала. В пятницу утром позвонила Виктору: Игорь в Бишкеке, вы свободны. Он поверил. Он мне всегда верит. — Дальше коротко, как диктант диктует: — Четверг, девять вечера. Автомат. Шестьдесят тысяч, иначе внучка. С Данияром собрали сорок. Суббота, пятнадцать тридцать, вот этот номер. Данияр отвёз деньги, вернулся. С половины восьмого до половины второго был со мной. — Кладёт пейджер. — Скажите Виктору сами. Я не смогу… Я ему в глаза не смогу.", "f725c4c5-f254-5c01-b718-3531a957102a": "Вы говорите: соседка Шмидтов видела Фархада у того дома. В субботу вечером, в четверть седьмого.\nВалентина Петровна встаёт. Подходит к серванту. За стеклом конверт, на нём её карандашом: «От Фархада — на похороны».\n— Двадцать лет. Вот на этом стуле. По пятницам плов. Игорь у него мальчишкой начинал… — Замолкает. — В воскресенье он пришёл. Вечером. Принёс вот это. А рука у него была расцарапана. Свежо так, красно. Я спросила. Собака, говорит, на базаре. — Пауза. — А уже в пальто, в прихожей, взял меня за локоть. Тихо так: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». И я подумала: ну хоть один… хоть один обо мне думает. — Закрывает дверцу серванта. — Больше не спрашивайте. Я не знаю, что это значит. Не знаю.", "27ae146a-a05c-5e7a-84a1-899c35e883e4": "Вы говорите: пальцы Мамаджанова сняты с люка подвала. Того, где держали Игоря.\nВалентина Петровна выходит в прихожую. Встаёт у зеркала, оно ещё завешено простынёй.\n— Вот здесь он стоял. В воскресенье. Уже в пальто. — Голос ровный, руки сцеплены. — Принёс конверт на похороны. Рука расцарапана, свежая. Я спросила. Собака на базаре, сказал. А здесь, у двери… взял за локоть: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Двадцать лет он у меня за столом сидел. Я тогда подумала: бережёт. Бережёт он меня. — Поправляет простыню, хотя та висит ровно. — Идите. Мне надо одной побыть.", "87af9a91-8540-5177-bdd6-3e156802fc75": "Валентина Петровна берёт шарф двумя руками. Долго молчит.\n— Его. Я из Москвы привезла. Итальянский.\n(прижимает к лицу)\nСыростью пахнет. Где он лежал? Нет... Не говорите. Не надо.", "4f67be3f-f5f7-5ab5-bb69-611053df3042": "— Даник говорил, что переписал номера. Я ещё рассердилась: зачем, лишь бы Игоря отпустили.\n(пауза)\nА он, выходит, правильно сделал. Один из нас.", "552b22f9-f4c6-5469-8d1c-56bde54906aa": "— Оттуда, значит, звонили. Из пустого дома.\n(закрывает глаза)\nА я сидела у аппарата и ждала. Думала, он где-то далеко. А он был в городе. Под землёй."}'::jsonb, '[{"id": "R08", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Валентина Петровна смотрит на красные цифры АОН. Потом на свой блокнот.\n— Игорь поставил. Чтобы я знала, кто звонит. Ну вот. Знаю. — Садится, спинки стула не касается. — В четверг. Около девяти. Из автомата. Шестьдесят тысяч долларов. Пойдёте в милицию — Дашу не увидите. — Пауза. — Мы с Данияром собрали сорок. Больше не было. Не было больше.\nВ субботу, в половине четвёртого, ещё раз. Вот этот номер. Данияр рядом стоял, видел. Он отвёз деньги. Вернулся. И мы сидели. С половины восьмого до половины второго, здесь, у телефона. Ждали. — Нажимает кнопку, цифры гаснут. — Он так радовался этой коробочке. «Мама, теперь ты всё будешь знать».", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R09", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["1ac01ab0-e8f1-5009-9640-d18dfa4f5e44"], "text": "Вы кладёте перед ней заключение Кана и пейджер из арыка. Говорите: молчание Дашу не защитит. Защитить её может только милиция.\nНа кухне перестают звенеть посудой.\n— Я тридцать лет учила детей говорить правду. Тридцать лет. А сама… — Долгая пауза. — Хорошо. Хорошо. Четверг, около девяти. Автомат. Шестьдесят тысяч, иначе внучку не увидим. Мы с Данияром собрали сорок. — Сбивается. — Суббота… половина четвёртого. Второй звонок, номер в АОН остался. Данияр отвёз деньги. Вернулся. С половины восьмого до половины второго был со мной. — Голос ломается. — Я молчала, чтобы уберечь Дашу. А вышло… как у плохой ученицы. Молчит, потому что не выучила.", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R46", "on": "1ac01ab0-e8f1-5009-9640-d18dfa4f5e44", "requires": ["e4e94374-000e-52e3-bb26-9bec42b1c55b"], "text": "Валентина Петровна берёт пейджер. Смотрит на АОН. На блокнот, где цифры её почерком.\n— Его пейджер. В арыке, у ворот… Он не уезжал в Бишкек. — Пауза. — Это я придумала. В пятницу утром позвонила Виктору: Игорь в Бишкеке, вы свободны. Он поверил. Он мне всегда верит. — Дальше коротко, как диктант диктует: — Четверг, девять вечера. Автомат. Шестьдесят тысяч, иначе внучка. С Данияром собрали сорок. Суббота, пятнадцать тридцать, вот этот номер. Данияр отвёз деньги, вернулся. С половины восьмого до половины второго был со мной. — Кладёт пейджер. — Скажите Виктору сами. Я не смогу… Я ему в глаза не смогу.", "grants": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "group": "group-1", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R65", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Вы говорите: соседка Шмидтов видела Фархада у того дома. В субботу вечером, в четверть седьмого.\nВалентина Петровна встаёт. Подходит к серванту. За стеклом конверт, на нём её карандашом: «От Фархада — на похороны».\n— Двадцать лет. Вот на этом стуле. По пятницам плов. Игорь у него мальчишкой начинал… — Замолкает. — В воскресенье он пришёл. Вечером. Принёс вот это. А рука у него была расцарапана. Свежо так, красно. Я спросила. Собака, говорит, на базаре. — Пауза. — А уже в пальто, в прихожей, взял меня за локоть. Тихо так: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». И я подумала: ну хоть один… хоть один обо мне думает. — Закрывает дверцу серванта. — Больше не спрашивайте. Я не знаю, что это значит. Не знаю.", "grants": ["e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c"], "group": "group-2", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R66", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "Вы говорите: пальцы Мамаджанова сняты с люка подвала. Того, где держали Игоря.\nВалентина Петровна выходит в прихожую. Встаёт у зеркала, оно ещё завешено простынёй.\n— Вот здесь он стоял. В воскресенье. Уже в пальто. — Голос ровный, руки сцеплены. — Принёс конверт на похороны. Рука расцарапана, свежая. Я спросила. Собака на базаре, сказал. А здесь, у двери… взял за локоть: «Бандиты сейчас такие, Валентина-апа. Береги Дашу. Никому ни слова». Двадцать лет он у меня за столом сидел. Я тогда подумала: бережёт. Бережёт он меня. — Поправляет простыню, хотя та висит ровно. — Идите. Мне надо одной побыть.", "grants": ["e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c"], "group": "group-2", "repeat_text": "«Я вам уже всё рассказала. Больше мне добавить нечего»."}, {"id": "R69", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "Валентина Петровна берёт шарф двумя руками. Долго молчит.\n— Его. Я из Москвы привезла. Итальянский.\n(прижимает к лицу)\nСыростью пахнет. Где он лежал? Нет... Не говорите. Не надо.", "grants": []}, {"id": "R83", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Даник говорил, что переписал номера. Я ещё рассердилась: зачем, лишь бы Игоря отпустили.\n(пауза)\nА он, выходит, правильно сделал. Один из нас.", "grants": []}, {"id": "R84", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Оттуда, значит, звонили. Из пустого дома.\n(закрывает глаза)\nА я сидела у аппарата и ждала. Думала, он где-то далеко. А он был в городе. Под землёй.", "grants": []}]'::jsonb, null, false, false, true, (select portrait_url from characters where name ilike 'Валентина%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('753087d6-7c38-5bf7-889e-3c4477902369', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Зоя Михайловна Лукина', 'Соседка Валентины по лестничной площадке в старом доме на Калинина, бухгалтер на пенсии', 'Зоя Михайловна Лукина, 63 года. Бухгалтер на пенсии. Соседка по площадке.
На кухне распоряжается она: мохеровый берет, полотенце через плечо. Видит удостоверение, поправляет берет.
— Лукина, Зоя Михайловна. Дверь напротив, тридцать лет на этой площадке. Курящих прошу на балкон, и дверь за собой. Спрашивайте, я тут до вечера.', '[{"q": "Вы хорошо знали Игоря?", "a": "— С пелёнок. Вот такой был. — Показывает ладонью от пола. — Вежливый. Здоровался всегда, сумки мне до двери носил. Не курил, между прочим. Это я отдельно говорю. — Поджимает губы. — Последние годы редко приезжал. На иномарке. Я не сплетничаю, я констатирую: к матери надо ездить чаще. Чаще надо."}, {"q": "Кто сейчас приходит к Валентине Петровне?", "a": "— Все ходят. Из школы её бывшие, родня, с его работы. Курящие, некурящие… я всех на балкон. — Кивает в сторону кухни. — А Фархад-ака с утра здесь. Вот кто человек. И хлеба принёс, и Валентину Петровну под руку держит, не отходит. — Пауза. — Я не сплетничаю, я констатирую. У человека горе, а он тут."}, {"q": "Вы что-нибудь слышали в выходные?", "a": "— Стены здесь толстые. Дом старый. Но я слышала. Что-то у неё стряслось: ходила, ходила… ночью не ложилась. — Мнёт полотенце. — Я не спросила. Думала, давление. У нас у всех давление. — Пауза. — Надо было спросить. Вы это не записывайте. Не записывайте, я прошу.", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}]'::jsonb, '{"b170d031-ba6c-5e70-829f-cbd96f761931": "Зоя Михайловна всё это время стоит в дверях кухни. Полотенце через плечо. Откашливается.\n— Я не сплетничаю. Я констатирую. Если Валентина Петровна говорит, что Данияр в субботу был здесь, — значит, был. «Девятка» его белая под моим окном стояла. С вечера и до глубокой ночи. Он её вечно колесом на газон ставит, я ему сто раз… — Машет рукой. — А около десяти, перед вторым «Временем», опять потянуло табаком. Я вышла на площадку. Стоит, курит. Заграничные. И окурки в банку у мусоропровода. Я ему говорю: молодой человек, тут люди живут.", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e": "— Данияр? Говорит, был здесь в субботу? — Зоя Михайловна поджимает губы. — Был. Я не сплетничаю, я констатирую. «Девятка» его белая под окном стояла. С вечера до глубокой ночи. Я её видела, когда шторы задёргивала. И ещё раз, когда телевизор выключала. — Пауза. — А около десяти, перед вторым «Временем», он на лестнице курил. Я вышла сказать: у нас тут не вокзал. Он извинился. Вежливый. Но курил."}'::jsonb, '[{"id": "R54", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Зоя Михайловна всё это время стоит в дверях кухни. Полотенце через плечо. Откашливается.\n— Я не сплетничаю. Я констатирую. Если Валентина Петровна говорит, что Данияр в субботу был здесь, — значит, был. «Девятка» его белая под моим окном стояла. С вечера и до глубокой ночи. Он её вечно колесом на газон ставит, я ему сто раз… — Машет рукой. — А около десяти, перед вторым «Временем», опять потянуло табаком. Я вышла на площадку. Стоит, курит. Заграничные. И окурки в банку у мусоропровода. Я ему говорю: молодой человек, тут люди живут.", "grants": ["4e8b269e-8c91-5629-b60d-13930fa7e61e"]}, {"id": "R55", "on": "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "requires": [], "text": "— Данияр? Говорит, был здесь в субботу? — Зоя Михайловна поджимает губы. — Был. Я не сплетничаю, я констатирую. «Девятка» его белая под окном стояла. С вечера до глубокой ночи. Я её видела, когда шторы задёргивала. И ещё раз, когда телевизор выключала. — Пауза. — А около десяти, перед вторым «Временем», он на лестнице курил. Я вышла сказать: у нас тут не вокзал. Он извинился. Вежливый. Но курил.", "grants": ["4e8b269e-8c91-5629-b60d-13930fa7e61e"]}]'::jsonb, null, false, false, true, 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-zoya-portrait.jpg');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('5b4c1ece-ba00-50d6-9113-73e03e05ccd8', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '78a34a22-6cc3-50d3-b3a7-bf4a481856bc', 'Фархад Мамаджанов', 'Бывший начальник отдела снабжения госбазы, в 1992 году — соучредитель кооператива вместе с Игорем', 'Фархад Мамаджанов, 49 лет. Друг семьи.
Стоит в дверях кухни, в старом драповом пальто. Держит Валентину Петровну под локоть. Кивает первым.
— Мамаджанов. Фархад. Если что нужно, дорогой, я тут. Тут я.', '[{"q": "Кем вы приходитесь семье?", "a": "— Друг, дорогой. Просто друг. Двадцать лет за этим столом. Игорь у меня в госснабе начинал, инженером. Мальчишка совсем, глаза горят… — Улыбается. — Потом кооператив вместе открыли. В девяносто втором. А потом жизнь развела. Ну, бывает. Так бывает, слушай."}, {"q": "Когда вы последний раз видели Игоря?", "a": "— Осенью. На базу к нему заходил, по старой памяти. Посидели. Поговорили. Хорошо поговорили, слушай, по-хорошему. — Качает головой. — Кто ж знал, что последний раз. Кто ж знал."}, {"q": "Чем занимается ваш племянник Олжас?", "a": "— Олжас? — Фархад кашляет. Глухо, долго. Вытирает губы платком. — Хороший мальчик. Из аула. Сестры моей двоюродной сын. Мешки таскает на Зелёном, в общаге живёт. Я ему: учись, дорогой. А он мне: аке, деньги нужны. — Разводит руками. — Ну что я ему скажу? Сам такой был. — Пауза. — Его не трогай, дорогой. Он тут ни при чём, слышишь?", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217", "6a92b637-cb0c-5bf4-8495-f503839bf08c"]}, {"q": "Где вы были в субботу вечером?", "a": "— Похитили?.. — Долго молчит. Садится. — И Валентина-апа мне ни слова. Двадцать лет — и ни слова. Ни слова, дорогой… — Трёт лицо ладонью. — Где был. Я же говорил тебе. Дома, в «Орбите». Один, Зарина у родни в Ташкенте. Свет у нас отключили, сидел при свечке. Чай пил. Никуда не выходил. Кто ж знал, что в ту ночь…", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"]}, {"q": "Вы знаете дом Шмидтов в Горном Гиганте?", "a": "— Шмидтов? Знаю, как не знать. Хорошие люди. Уехали к своим, в Германию. Дом их продаю, помогаю. Сейчас все продают, дорогой. — Отмахивается. — Только я там с октября не был. Ключи покупателю отдал. Какому — не помню, слушай. У меня их десять было, покупателей. Десять.", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"q": "Где ваша дочь?", "a": "— В Ташкенте. У родни. С четверга. — Впервые смотрит без обиды. Со страхом. — Её не трогай. Она ничего не знает. Ничего, слышишь? Хочешь меня — бери меня. Меня бери.", "requires": ["cefb9e58-2cc4-5054-a43b-6216c7645217"]}]'::jsonb, '{"43eaf70c-177d-516a-9ab2-7aecc9633e33": "Фархад берёт протокол двумя руками. Левая кисть в бинте.\nЧитает долго, шевелит губами.\n— Угорел… Грелся, значит. Эх, Игорь, Игорь. — Поднимает глаза. — Мы с ним давно помирились, дорогой, ты не думай. Зла не держал. Дай бог каждому такого друга. — Замечает, куда вы смотрите. Приподнимает руку. — Это? Казан. Плов делал, обжёгся, как мальчишка. Заживёт. — Пауза. — А у нас в «Орбите» в субботу тоже свет отключили. Сидел один при свечке. Чай пил. Зарина моя у родни в Ташкенте, с четверга. Думал, Игорь позвонит, а он… — Разглаживает протокол ладонью. — Пойду к Валентине-апа. Ей сейчас одной нельзя.", "009a36f7-b362-586d-8943-61cd46149c3c": "Кабинет. Фархад без пальто, в старом свитере. Перед ним запись КПП за двадцать восьмое октября и показания Ахметова.\nОн долго молчит. Потом тихо, уже без «дорогой»:\n— Помирились… Нет. Не помирились. Я за него сидел. Полтора года. Ты знаешь, что такое полтора года, когда тебе сорок семь? — Пауза. — Он обещал: доля твоя, семья твоя под присмотром. Я вышел. А базы моей нет. Есть их АО. Я к нему пришёл по-человечески. А он мне — «завскладом». При своём счетоводе, при нём. — Кашляет. — Да. Обиделся. Только обиду в милицию не носят, слушай. Обида — не преступление.", "64b699fc-69d6-5bc3-ab81-b5a48df561bd": "Фархад смотрит на справку электросетей. Долго.\n— Был свет? — Пожимает плечами. — Ну, значит, перепутал. Не в субботу отключали. В пятницу. — Вы кладёте рядом показания соседки Шмидтов: белая «Волга», одна фара, четверть седьмого. Он кашляет, до слёз, вытирает глаза ладонью. — Ну заезжал. Да. Чего ты так смотришь? Дом показывал покупателю. Дом по доверенности на мне, я право имею. Посидели с лампой, света ж там не было. Он уехал, я тоже. — Пауза. — А со свечкой дома перепутал, говорю тебе. У нас в пятницу отключали. В пятницу. — Голос уже не отеческий. — Всё. Устал я, слушай.", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3": "Фархад смотрит на свою кисть. Голая, без бинта.\n— Ногти… Собака это. На базаре. — И сам себя поправляет: — Казан. Обжёгся я. — Пауза. Кан при понятых сказал: ожога нет. Он это слышал. — Казан, собака… Какая разница, дорогой? Вторая группа у половины базара. Ты меня за группу крови посадишь? — Отворачивается к окну. Молчит долго. Потом не вам: — Зарина… Дочка у меня. Семнадцать лет. — И замолкает.\nНа этот допрос его больше не хватает.", "27ae146a-a05c-5e7a-84a1-899c35e883e4": "— Пальцы на лампе? — Фархад усмехается углом рта. — Мои, конечно. Я этот дом продаю. Лампы трогал, двери трогал. Всё трогал. — Вы напоминаете про люк в подвал. И про соседку: «Волга» у калитки, суббота, вечер. Он молчит. — Говорил, с октября не был… Ну. Заезжал. В субботу. Покупателю дом показывал. Посидели с лампой, света ж не было. Он уехал, я тоже. — Пауза. — А про свечку дома перепутал. У нас в пятницу отключали. — Смотрит прямо. — Ты молодой ещё, дорогой. Не ищи там, где не надо. Иногда лучше не найти.", "26a10711-a53c-5105-9ed4-190697869496": "Фархад смотрит на протокол сравнения купюр. Лицо у него каменеет.\n— Это от сердца было. — Пауза. Совсем тихо: — Валентине-апа не говори. Как человека прошу. Двадцать лет я за её столом… Пусть думает, что от сердца. Пусть думает. — Прячет руки в рукава свитера. Смотрит мимо вас, на дверь кабинета. — Больше ничего не скажу. Делай свою работу, дорогой.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "Фархад отмахивается перевязанной рукой.\n— Конверт? Я принёс, да. Свои. От сердца. Похороны сейчас сам знаешь сколько… а Валентина-апа одна. — Видит, что вы смотрите на бинт. — Это? Казан. Обжёгся. Не обращай внимания, дорогой. — Пауза. — Мы с Игорем давно помирились. Что было, то было. Зла не держу. В субботу у себя в «Орбите» сидел. Один, Зарина у родни в Ташкенте. Свет отключили, при свечке сидел. Кто ж знал, что он в ту ночь… — Не договаривает. — Ты её сегодня не мучай, дорогой. Она держится. Но это снаружи.", "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c": "Олжаса уводят. Фархад смотрит на закрытую дверь. Потом говорит медленно, по-отечески. В последний раз.\n— Мальчика пожалей. Он не знал. Я ему сказал: никто не пострадает. Я и сам тогда верил. — Пауза. — Слушай сюда. Ерлану я долг списал. За четверги. Больше он ничего не знал. Игоря мы взяли. Я долю хотел. Свою. Только долю, понимаешь? — Кашляет. — А потом Олжас приходит: он тебя узнал. И я понял. Живой — он меня посадит. А Зарина одна останется. С моими долгами. Они к ней уже приходили, к дочке моей… — Долго молчит. — Я его сам. Один. Потом на Кок-Тобе отвёз, на его же машине. Мотор завёл. Вниз пешком. Внизу частника поймал, номера не помню, не спрашивай. Часть денег кредитору отдал. Остальное ты нашёл. — Поднимает глаза. — Пощады не прошу. Дочку только не трогайте.", "f725c4c5-f254-5c01-b718-3531a957102a": "Вы читаете Фархаду показания Шнайдер. Строчку за строчкой. Из «Волги» вышли двое: он и высокий парень. Парень скоро ушёл пешком. Больше в тот вечер никто не приезжал. «Волга» стояла у калитки до половины второго ночи. Уехала по свежему снегу.\nФархад смотрит на свои руки.\n— Покупатель… — И не заканчивает. Долго кашляет. — Не спит старуха, значит. Всё видит. — Пауза. — Сейчас спросишь, как его зовут. Не спрашивай, дорогой. Нету его.\nБольше на этот допрос он ничего не говорит.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "Фархад одёргивает рукав пальто, прячет руку.\n— Ерунда. Поранился. По хозяйству.\n(кашляет в кулак)\nЗаживёт. Вы не за этим пришли, товарищ следователь.", "4cc34317-760f-577c-b05f-e0374aee4f23": "— Ну, был на базе. В октябре. К Игорю зашёл, по старой памяти.\n(пожимает плечами)\nПоговорили и разошлись. Что тут записывать? Охрана у них от скуки всех пишет.", "00b31a8e-e1ee-5474-a323-177b43b153d3": "— Обыск, значит, сделали. Ну, мои ботинки. Зимние. Сорок третий.\n(долго смотрит на каблук)\nПорез? Где-то зацепил. Мало ли где человек ходит, товарищ следователь.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "— Это мои сбережения. Всю жизнь копил.\nВ банк сейчас только дурак понесёт: сегодня банк есть, завтра нет.\n(отворачивается)\nА бумаги Шмидтов у меня по доверенности. Дом продаю, люди попросили.", "b322dfba-0cb0-52bc-9610-328a905bc004": "— Долги отдавал. Людям.\nЯ в девяносто третьем всё потерял на этих фондах, как и полгорода. Занимал, теперь отдаю.\nЭто что, запрещено?", "6a92b637-cb0c-5bf4-8495-f503839bf08c": "— Олжас? Племянник. Сестры сын.\nИз аула приехал, на базаре грузит. Я ему помогаю, как могу. Мальчик хороший.\n(резко)\nЕго не трогайте. Он тут ни при чём.", "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c": "— Валя-апа переживает, ей всякое кажется.\nСобака это. На базаре, у мясных рядов. Я же ей говорил.\n(прячет руку)", "e34a96b0-5d0e-5414-9ef3-048071ef84ed": "Фархад долго молчит. Кашляет.\n— Игорь... Двадцать лет его знал. Мальчишкой ко мне пришёл.\n(отворачивается)\nНе надо мне это показывать, товарищ следователь.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "— Подвал как подвал. Я дом продаю, по доверенности.\nВ подвал не лазил, что мне там делать.\n(кашляет)\nПокупателям кухню показывал, комнаты.", "87af9a91-8540-5177-bdd6-3e156802fc75": "— Шарф...\n(не смотрит)\nМало ли у кого какие шарфы. Не знаю."}'::jsonb, '[{"id": "R07", "on": "43eaf70c-177d-516a-9ab2-7aecc9633e33", "requires": [], "text": "Фархад берёт протокол двумя руками. Левая кисть в бинте.\nЧитает долго, шевелит губами.\n— Угорел… Грелся, значит. Эх, Игорь, Игорь. — Поднимает глаза. — Мы с ним давно помирились, дорогой, ты не думай. Зла не держал. Дай бог каждому такого друга. — Замечает, куда вы смотрите. Приподнимает руку. — Это? Казан. Плов делал, обжёгся, как мальчишка. Заживёт. — Пауза. — А у нас в «Орбите» в субботу тоже свет отключили. Сидел один при свечке. Чай пил. Зарина моя у родни в Ташкенте, с четверга. Думал, Игорь позвонит, а он… — Разглаживает протокол ладонью. — Пойду к Валентине-апа. Ей сейчас одной нельзя.", "grants": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "abc6fac8-abbd-5589-b6b5-958cd368e7fe"]}, {"id": "R31", "on": "009a36f7-b362-586d-8943-61cd46149c3c", "requires": ["4cc34317-760f-577c-b05f-e0374aee4f23"], "text": "Кабинет. Фархад без пальто, в старом свитере. Перед ним запись КПП за двадцать восьмое октября и показания Ахметова.\nОн долго молчит. Потом тихо, уже без «дорогой»:\n— Помирились… Нет. Не помирились. Я за него сидел. Полтора года. Ты знаешь, что такое полтора года, когда тебе сорок семь? — Пауза. — Он обещал: доля твоя, семья твоя под присмотром. Я вышел. А базы моей нет. Есть их АО. Я к нему пришёл по-человечески. А он мне — «завскладом». При своём счетоводе, при нём. — Кашляет. — Да. Обиделся. Только обиду в милицию не носят, слушай. Обида — не преступление.", "grants": []}, {"id": "R32", "on": "64b699fc-69d6-5bc3-ab81-b5a48df561bd", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Фархад смотрит на справку электросетей. Долго.\n— Был свет? — Пожимает плечами. — Ну, значит, перепутал. Не в субботу отключали. В пятницу. — Вы кладёте рядом показания соседки Шмидтов: белая «Волга», одна фара, четверть седьмого. Он кашляет, до слёз, вытирает глаза ладонью. — Ну заезжал. Да. Чего ты так смотришь? Дом показывал покупателю. Дом по доверенности на мне, я право имею. Посидели с лампой, света ж там не было. Он уехал, я тоже. — Пауза. — А со свечкой дома перепутал, говорю тебе. У нас в пятницу отключали. В пятницу. — Голос уже не отеческий. — Всё. Устал я, слушай.", "grants": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"]}, {"id": "R33", "on": "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3", "requires": [], "text": "Фархад смотрит на свою кисть. Голая, без бинта.\n— Ногти… Собака это. На базаре. — И сам себя поправляет: — Казан. Обжёгся я. — Пауза. Кан при понятых сказал: ожога нет. Он это слышал. — Казан, собака… Какая разница, дорогой? Вторая группа у половины базара. Ты меня за группу крови посадишь? — Отворачивается к окну. Молчит долго. Потом не вам: — Зарина… Дочка у меня. Семнадцать лет. — И замолкает.\nНа этот допрос его больше не хватает.", "grants": []}, {"id": "R34", "on": "27ae146a-a05c-5e7a-84a1-899c35e883e4", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "— Пальцы на лампе? — Фархад усмехается углом рта. — Мои, конечно. Я этот дом продаю. Лампы трогал, двери трогал. Всё трогал. — Вы напоминаете про люк в подвал. И про соседку: «Волга» у калитки, суббота, вечер. Он молчит. — Говорил, с октября не был… Ну. Заезжал. В субботу. Покупателю дом показывал. Посидели с лампой, света ж не было. Он уехал, я тоже. — Пауза. — А про свечку дома перепутал. У нас в пятницу отключали. — Смотрит прямо. — Ты молодой ещё, дорогой. Не ищи там, где не надо. Иногда лучше не найти.", "grants": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"]}, {"id": "R35", "on": "26a10711-a53c-5105-9ed4-190697869496", "requires": [], "text": "Фархад смотрит на протокол сравнения купюр. Лицо у него каменеет.\n— Это от сердца было. — Пауза. Совсем тихо: — Валентине-апа не говори. Как человека прошу. Двадцать лет я за её столом… Пусть думает, что от сердца. Пусть думает. — Прячет руки в рукава свитера. Смотрит мимо вас, на дверь кабинета. — Больше ничего не скажу. Делай свою работу, дорогой.", "grants": []}, {"id": "R37", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "Фархад отмахивается перевязанной рукой.\n— Конверт? Я принёс, да. Свои. От сердца. Похороны сейчас сам знаешь сколько… а Валентина-апа одна. — Видит, что вы смотрите на бинт. — Это? Казан. Обжёгся. Не обращай внимания, дорогой. — Пауза. — Мы с Игорем давно помирились. Что было, то было. Зла не держу. В субботу у себя в «Орбите» сидел. Один, Зарина у родни в Ташкенте. Свет отключили, при свечке сидел. Кто ж знал, что он в ту ночь… — Не договаривает. — Ты её сегодня не мучай, дорогой. Она держится. Но это снаружи.", "grants": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "abc6fac8-abbd-5589-b6b5-958cd368e7fe"]}, {"id": "R36", "on": "3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c", "requires": ["6fc41a46-a0eb-5890-9b26-3b19bcef490d", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"], "text": "Олжаса уводят. Фархад смотрит на закрытую дверь. Потом говорит медленно, по-отечески. В последний раз.\n— Мальчика пожалей. Он не знал. Я ему сказал: никто не пострадает. Я и сам тогда верил. — Пауза. — Слушай сюда. Ерлану я долг списал. За четверги. Больше он ничего не знал. Игоря мы взяли. Я долю хотел. Свою. Только долю, понимаешь? — Кашляет. — А потом Олжас приходит: он тебя узнал. И я понял. Живой — он меня посадит. А Зарина одна останется. С моими долгами. Они к ней уже приходили, к дочке моей… — Долго молчит. — Я его сам. Один. Потом на Кок-Тобе отвёз, на его же машине. Мотор завёл. Вниз пешком. Внизу частника поймал, номера не помню, не спрашивай. Часть денег кредитору отдал. Остальное ты нашёл. — Поднимает глаза. — Пощады не прошу. Дочку только не трогайте.", "grants": ["20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db"]}, {"id": "R63", "on": "f725c4c5-f254-5c01-b718-3531a957102a", "requires": ["7188cb7d-2261-5a9c-8f78-e603caa6b31a"], "text": "Вы читаете Фархаду показания Шнайдер. Строчку за строчкой. Из «Волги» вышли двое: он и высокий парень. Парень скоро ушёл пешком. Больше в тот вечер никто не приезжал. «Волга» стояла у калитки до половины второго ночи. Уехала по свежему снегу.\nФархад смотрит на свои руки.\n— Покупатель… — И не заканчивает. Долго кашляет. — Не спит старуха, значит. Всё видит. — Пауза. — Сейчас спросишь, как его зовут. Не спрашивай, дорогой. Нету его.\nБольше на этот допрос он ничего не говорит.", "grants": []}, {"id": "R71", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "Фархад одёргивает рукав пальто, прячет руку.\n— Ерунда. Поранился. По хозяйству.\n(кашляет в кулак)\nЗаживёт. Вы не за этим пришли, товарищ следователь.", "grants": []}, {"id": "R72", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "— Ну, был на базе. В октябре. К Игорю зашёл, по старой памяти.\n(пожимает плечами)\nПоговорили и разошлись. Что тут записывать? Охрана у них от скуки всех пишет.", "grants": []}, {"id": "R73", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": [], "text": "— Обыск, значит, сделали. Ну, мои ботинки. Зимние. Сорок третий.\n(долго смотрит на каблук)\nПорез? Где-то зацепил. Мало ли где человек ходит, товарищ следователь.", "grants": []}, {"id": "R74", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Это мои сбережения. Всю жизнь копил.\nВ банк сейчас только дурак понесёт: сегодня банк есть, завтра нет.\n(отворачивается)\nА бумаги Шмидтов у меня по доверенности. Дом продаю, люди попросили.", "grants": []}, {"id": "R75", "on": "b322dfba-0cb0-52bc-9610-328a905bc004", "requires": [], "text": "— Долги отдавал. Людям.\nЯ в девяносто третьем всё потерял на этих фондах, как и полгорода. Занимал, теперь отдаю.\nЭто что, запрещено?", "grants": []}, {"id": "R76", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Олжас? Племянник. Сестры сын.\nИз аула приехал, на базаре грузит. Я ему помогаю, как могу. Мальчик хороший.\n(резко)\nЕго не трогайте. Он тут ни при чём.", "grants": []}, {"id": "R77", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "— Валя-апа переживает, ей всякое кажется.\nСобака это. На базаре, у мясных рядов. Я же ей говорил.\n(прячет руку)", "grants": []}, {"id": "R87", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Фархад долго молчит. Кашляет.\n— Игорь... Двадцать лет его знал. Мальчишкой ко мне пришёл.\n(отворачивается)\nНе надо мне это показывать, товарищ следователь.", "grants": []}, {"id": "R88", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "— Подвал как подвал. Я дом продаю, по доверенности.\nВ подвал не лазил, что мне там делать.\n(кашляет)\nПокупателям кухню показывал, комнаты.", "grants": []}, {"id": "R89", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "— Шарф...\n(не смотрит)\nМало ли у кого какие шарфы. Не знаю.", "grants": []}]'::jsonb, null, false, true, true, 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-farhad-portrait.jpg');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('a7955352-673d-5ff7-bfcc-506079544d1f', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Данияр Ахметов', 'Партнёр Игоря и финансист фирмы, по образованию экономист', 'Данияр Ахметов, 38 лет, финансовый директор и партнёр Сартакова. По образованию экономист.
Сидит за столом. Калькулятор, две ручки, параллельно.
— Ахметов. Чем могу... Да. Слушаю вас.', '[{"q": "Как дела у фирмы?", "a": "— В порядке. По состоянию на конец третьего квартала оборот выше прошлогоднего на двенадцать процентов. Задолженности по поставкам нет.\nИгорь мне доверял. Полностью. (поправляет ручку) Полностью."}, {"q": "Где вы были в субботу вечером?", "a": "— Дома. Один.\nС девятнадцати ноль-ноль... примерно. И до утра. Телевизор смотрел. Какая программа — не помню.\nЭто важно?"}, {"q": "Игорь кричал на вас: «Месяц тебе, или сядешь». Это о чём?", "a": "— Виктор, значит. (снимает очки, кладёт дужками вверх) Хорошо.\nБыл вопрос по деньгам. Я выводил средства на другую фирму. Полгода.\nХотел квартиру в Москве купить и уехать. Здесь же всё рухнет, вы же видите.\nИгорь нашёл платёжки. Дал месяц вернуть. Я собирался вернуть, собирался.\nЭто хищение, я понимаю. Но не убийство.", "requires": ["0a295d5f-e115-5c89-a26a-5992761304a0"]}, {"q": "Зачем вы сняли копии купюр?", "a": "— Потому что не верил. Никому. Ни им, ни вам, извините.\nЕсли бы Игоря не отпустили — у кого-то должны были остаться номера.\nЯ финансист. Я всё копирую. (пауза) Это единственное, что я умею делать хорошо.", "requires": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"]}, {"q": "Кто приходил к Игорю на базу в последнее время?", "a": "— Все приходят. Поставщики, экспедиторы, кредиторы. Всех не упомнишь.\n(достаёт из сейфа толстую амбарную книгу)\nЖурнал КПП. На проходной пишут всех, кто входит. Берите, мне не жалко. Я, в отличие от некоторых, ничего не скрываю.", "grants_evidence_id": "4cc34317-760f-577c-b05f-e0374aee4f23"}]'::jsonb, '{"b170d031-ba6c-5e70-829f-cbd96f761931": "Данияр снимает очки. Кладёт на стол дужками вверх. Ровно.\n— Валентина Петровна сказала... Значит, всё.\nДа. Знал. С пятницы. Она запретила идти в милицию. Я согласился.\nСорок тысяч взял из кассы, которой официально нет. И вернул туда то, что раньше вывел.\nВ субботу в пятнадцать тридцать был у неё. Когда позвонили. Номер на АОН сам видел.\nОттуда с пакетом на Ташкентскую, на остановку. В семнадцать тридцать оставил под скамейкой.\nТемно уже. Парень... высокий, молодой. Спортивная куртка, ушанка. Лица не видел.\nПотом на базу. Въехал в семнадцать пятьдесят пять, выехал в девятнадцать десять. На КПП записано.\nВ девятнадцать тридцать вернулся к ней. До часу тридцати.\n(открывает нижний ящик) Копии всех купюр. Я не верил ни им, ни вам.", "e4e94374-000e-52e3-bb26-9bec42b1c55b": "Данияр смотрит на страницу блокнота. На лице что-то вроде облегчения.\n— Почерк Валентины Петровны. «Шестьдесят» — это тысяч. «Семнадцать тридцать, Ташкентская».\nВы уже всё поняли. (снимает очки)\nДа. С пятницы знал. В милицию не пошёл — она просила.\nСорок тысяч взял из «чёрной» кассы. Вернул туда то, что выводил.\nЭтот номер на АОН, в пятнадцать тридцать... я своими глазами видел. Я там был, когда звонили.\nВ семнадцать тридцать оставил пакет на остановке. Темно. Высокий, молодой. Спортивная куртка, ушанка. Лица — нет.\nПотом база. С семнадцати пятидесяти пяти до девятнадцати десяти, журнал КПП подтвердит.\nС половины восьмого до половины второго — опять у неё.\n(выдвигает ящик) Копии купюр. Все. Возьмите.", "4cc34317-760f-577c-b05f-e0374aee4f23": "Данияр долго смотрит на строчку в журнале.\n— Двадцать восьмое октября. Шестнадцать десять. Да.\nЯ был в кабинете. Фархад пришёл просить свою долю. Спокойно. Вежливо. В галстуке пришёл.\nВы знаете, что он сидел? В девяносто четвёртом. За товар нашей общей фирмы — взял на себя. Полтора года.\nИгорь ему тогда обещал всё сохранить.\nА тут при мне: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ничего не ответил. Встал и ушёл. Молча.\n(пауза) Я тогда подумал: лучше бы кричал.", "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba": "Данияр впервые повышает голос. И тут же снимает очки.\n— Помирились? Он так сказал?\nИгорь его выгнал. При мне. Двадцать восьмого октября, в кабинете.\nФархад пришёл свою долю просить. Вежливо. В галстуке.\nОн же в девяносто четвёртом сел за товар нашей общей фирмы. Всё на себя взял. Полтора года.\nА Игорь ему: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ушёл. Молча.\n(кладёт очки дужками вверх) Если это «помирились»... я не знаю тогда, что такое ссора.", "0a295d5f-e115-5c89-a26a-5992761304a0": "— Виктор, значит.\n(снимает очки)\nБыл разговор. По деньгам. Партнёры иногда ругаются.\nК тому, что с Игорем случилось, это отношения не имеет.", "9281d556-d163-5537-a0e2-e4cd2e635ba5": "— Значит, проверили. Хорошо.\n(выдыхает)\nЯ вам с самого начала говорил: я его не трогал. Деньги — да. Но не это.", "06da149b-c92c-54fa-a5f5-b78ff87dbc92": "— Вот видите. Сходится.\n(поправляет ручку на столе)\nЯ виноват перед Игорем. Но не в этом.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "— Фархад принёс. В воскресенье вечером, я там был.\nВалентина Петровна плакала, а он её по руке гладил.\n(пожимает плечами)\nПятьсот долларов у человека, который всем должен. Я тогда ещё подумал: откуда."}'::jsonb, '[{"id": "R14", "on": "b170d031-ba6c-5e70-829f-cbd96f761931", "requires": [], "text": "Данияр снимает очки. Кладёт на стол дужками вверх. Ровно.\n— Валентина Петровна сказала... Значит, всё.\nДа. Знал. С пятницы. Она запретила идти в милицию. Я согласился.\nСорок тысяч взял из кассы, которой официально нет. И вернул туда то, что раньше вывел.\nВ субботу в пятнадцать тридцать был у неё. Когда позвонили. Номер на АОН сам видел.\nОттуда с пакетом на Ташкентскую, на остановку. В семнадцать тридцать оставил под скамейкой.\nТемно уже. Парень... высокий, молодой. Спортивная куртка, ушанка. Лица не видел.\nПотом на базу. Въехал в семнадцать пятьдесят пять, выехал в девятнадцать десять. На КПП записано.\nВ девятнадцать тридцать вернулся к ней. До часу тридцати.\n(открывает нижний ящик) Копии всех купюр. Я не верил ни им, ни вам.", "grants": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "4f67be3f-f5f7-5ab5-bb69-611053df3042"]}, {"id": "R15", "on": "e4e94374-000e-52e3-bb26-9bec42b1c55b", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Данияр смотрит на страницу блокнота. На лице что-то вроде облегчения.\n— Почерк Валентины Петровны. «Шестьдесят» — это тысяч. «Семнадцать тридцать, Ташкентская».\nВы уже всё поняли. (снимает очки)\nДа. С пятницы знал. В милицию не пошёл — она просила.\nСорок тысяч взял из «чёрной» кассы. Вернул туда то, что выводил.\nЭтот номер на АОН, в пятнадцать тридцать... я своими глазами видел. Я там был, когда звонили.\nВ семнадцать тридцать оставил пакет на остановке. Темно. Высокий, молодой. Спортивная куртка, ушанка. Лица — нет.\nПотом база. С семнадцати пятидесяти пяти до девятнадцати десяти, журнал КПП подтвердит.\nС половины восьмого до половины второго — опять у неё.\n(выдвигает ящик) Копии купюр. Все. Возьмите.", "grants": ["ea60506a-dfdb-5176-a63a-2fd3c47f8b6e", "4f67be3f-f5f7-5ab5-bb69-611053df3042"]}, {"id": "R16", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "Данияр долго смотрит на строчку в журнале.\n— Двадцать восьмое октября. Шестнадцать десять. Да.\nЯ был в кабинете. Фархад пришёл просить свою долю. Спокойно. Вежливо. В галстуке пришёл.\nВы знаете, что он сидел? В девяносто четвёртом. За товар нашей общей фирмы — взял на себя. Полтора года.\nИгорь ему тогда обещал всё сохранить.\nА тут при мне: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ничего не ответил. Встал и ушёл. Молча.\n(пауза) Я тогда подумал: лучше бы кричал.", "grants": ["009a36f7-b362-586d-8943-61cd46149c3c"]}, {"id": "R43", "on": "6d8d58c7-784b-5d25-9f9e-d6c55f6966ba", "requires": ["54bf13bc-3525-5eec-9441-609d8ee21f59"], "text": "Данияр впервые повышает голос. И тут же снимает очки.\n— Помирились? Он так сказал?\nИгорь его выгнал. При мне. Двадцать восьмого октября, в кабинете.\nФархад пришёл свою долю просить. Вежливо. В галстуке.\nОн же в девяносто четвёртом сел за товар нашей общей фирмы. Всё на себя взял. Полтора года.\nА Игорь ему: «Я тебя садиться не просил. Хочешь — иди завскладом».\nФархад ушёл. Молча.\n(кладёт очки дужками вверх) Если это «помирились»... я не знаю тогда, что такое ссора.", "grants": ["009a36f7-b362-586d-8943-61cd46149c3c"]}, {"id": "R78", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Виктор, значит.\n(снимает очки)\nБыл разговор. По деньгам. Партнёры иногда ругаются.\nК тому, что с Игорем случилось, это отношения не имеет.", "grants": []}, {"id": "R79", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Значит, проверили. Хорошо.\n(выдыхает)\nЯ вам с самого начала говорил: я его не трогал. Деньги — да. Но не это.", "grants": []}, {"id": "R80", "on": "06da149b-c92c-54fa-a5f5-b78ff87dbc92", "requires": [], "text": "— Вот видите. Сходится.\n(поправляет ручку на столе)\nЯ виноват перед Игорем. Но не в этом.", "grants": []}, {"id": "R85", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "— Фархад принёс. В воскресенье вечером, я там был.\nВалентина Петровна плакала, а он её по руке гладил.\n(пожимает плечами)\nПятьсот долларов у человека, который всем должен. Я тогда ещё подумал: откуда.", "grants": []}]'::jsonb, null, false, true, true, (select portrait_url from characters where name ilike '%Данияр%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('2d9e7245-2e05-5079-86f1-f9b2edb1f3e9', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '92cac3d9-0cc0-5a14-b4bc-91a65f6e04ed', 'Ерлан Нуртазин', 'Бывший сержант милиции, уволен в 1994 году после истории со взяткой', 'Ерлан Нуртазин, 34 года, охранник на КПП базы. Бывший сержант милиции, уволен в девяносто четвёртом.
Увидев удостоверение, встаёт. Привычка. И тут же садится.
— Нуртазин. Охрана объекта. Слушаю, братан. Это... слушаю.', '[{"q": "Где вы были в субботу вечером?", "a": "— Находился на посту. С двадцати ноль-ноль до восьми ноль-ноль, смена.\nОтзвоны на пульт агентства — каждый час. Журнал смены у старшего.\nПроверяйте. Я бы сам проверил, братан. Ну, на вашем месте."}, {"q": "Кто знал, что Игорь по четвергам ездит один?", "a": "— Да все знали. КПП, офис, грузчики.\nОн в пять водилу отпускал — и сам за руль. Тайна, тоже мне."}, {"q": "Фархада Мамаджанова знаете?", "a": "— Мамаджанова? (пепел падает на колено) Ну... почти не знаю.\nВидел пару раз на базе. Давно. Пожилой такой. Кашляет.\nА что?", "requires": ["6d8d58c7-784b-5d25-9f9e-d6c55f6966ba"]}, {"q": "Почему молчали?", "a": "— А ты знаешь, как бывшие менты сидят? Вот.\nЯ думал: разговор у них. Мужской.\nА потом его нашли. И я себе сказал: угорел. Угорел, и всё. (тушит сигарету мимо пепельницы) Так легче было.", "requires": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"]}, {"q": "Покажите ваш пейджер.", "a": "— Пейджер? Зачем? Служебный.\n(отстёгивает с ремня, не сразу)\nНа. Там пусто, смотри сколько хочешь.", "grants_evidence_id": "be5c249c-d25f-5239-865f-5aef2088bc61"}]'::jsonb, '{"c50332f2-fb14-5cff-9ea2-9581024ac2e3": "Ерлан читает листок. Пепел с сигареты падает на колено.\n— Да чё ты... Ладно. Ладно, братан.\nФархад. В девяносто третьем мать на операцию легла. Надо было полторы тысячи долларов. Он дал. Без расписки.\nЯ не вернул. Меня из органов попёрли — какие деньги.\nА за две недели до всего — в субботу, девятого — в чайхане у Зелёного он мне говорит: забудь долг. Только скажи, когда Игорь один ездит. Поговорить, мол, по-мужски. Без водилы.\nНу я и сказал: по четвергам.\nВ четверг он мне на пейджер: «в силе?». Я перезвонил. В силе.\nВсё. Думал — разговор.\nВ субботу находился на посту, с двадцати до восьми, отзвоны на пульт каждый час.\n(трёт колено) А когда Игоря нашли... гнал от себя. Молчал.", "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db": "Ерлан слушает выдержку из показаний. Тушит сигарету о край стола, мимо пепельницы.\n— Сдал, значит, Фархад-ака. Ну да.\nБыло. В девяносто третьем он мне полторы тысячи дал. На операцию матери. Я не вернул.\nА девятого, в субботу, в чайхане у Зелёного — недели за две до всего — говорит: спишу. Только скажи, когда Игорь без водилы ездит. Поговорить надо. По-мужски.\nЯ сказал: по четвергам.\nВ четверг на пейджер пришло: «в силе?». Я перезвонил, подтвердил.\nБольше ничего не знал, хоть режь. Думал — разговор.\nВ субботу на смене был. С двадцати до восьми, отзвоны на пульт каждый час. Проверяй."}'::jsonb, '[{"id": "R21", "on": "c50332f2-fb14-5cff-9ea2-9581024ac2e3", "requires": [], "text": "Ерлан читает листок. Пепел с сигареты падает на колено.\n— Да чё ты... Ладно. Ладно, братан.\nФархад. В девяносто третьем мать на операцию легла. Надо было полторы тысячи долларов. Он дал. Без расписки.\nЯ не вернул. Меня из органов попёрли — какие деньги.\nА за две недели до всего — в субботу, девятого — в чайхане у Зелёного он мне говорит: забудь долг. Только скажи, когда Игорь один ездит. Поговорить, мол, по-мужски. Без водилы.\nНу я и сказал: по четвергам.\nВ четверг он мне на пейджер: «в силе?». Я перезвонил. В силе.\nВсё. Думал — разговор.\nВ субботу находился на посту, с двадцати до восьми, отзвоны на пульт каждый час.\n(трёт колено) А когда Игоря нашли... гнал от себя. Молчал.", "grants": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"]}, {"id": "R22", "on": "20f4e430-8a7c-5972-b9e5-b3a4d3d7d6db", "requires": [], "text": "Ерлан слушает выдержку из показаний. Тушит сигарету о край стола, мимо пепельницы.\n— Сдал, значит, Фархад-ака. Ну да.\nБыло. В девяносто третьем он мне полторы тысячи дал. На операцию матери. Я не вернул.\nА девятого, в субботу, в чайхане у Зелёного — недели за две до всего — говорит: спишу. Только скажи, когда Игорь без водилы ездит. Поговорить надо. По-мужски.\nЯ сказал: по четвергам.\nВ четверг на пейджер пришло: «в силе?». Я перезвонил, подтвердил.\nБольше ничего не знал, хоть режь. Думал — разговор.\nВ субботу на смене был. С двадцати до восьми, отзвоны на пульт каждый час. Проверяй.", "grants": ["b229ab87-5e5b-5f61-8a7b-18c17718e4cf"]}]'::jsonb, null, false, true, true, (select portrait_url from characters where name ilike 'Ерлан%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('631694f6-0ec1-523d-9f2a-599f875223c1', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', '9ee66fb3-ffa5-5945-8a41-2fb9ca9c14e7', 'Тамара Фёдоровна Шнайдер', 'Соседка Шмидтов через забор, вдова', 'Тамара Фёдоровна Шнайдер, 72 года. Вдова. Соседка Шмидтов через забор. Дети в Германии.
Над забором седая голова в шерстяном платке.
— Вы из милиции? Ну, Gott sei Dank. Наконец хоть кто-то. Я думала, у нас тут никто никогда ничего не спросит. Никто.', '[{"q": "Вы давно здесь живёте?", "a": "— С пятьдесят восьмого года, деточка. Дети мои в Германии уже третий год, в Кёльне. А я документы жду. Каждый месяц пишу, каждый месяц мне отвечают: ждите. Ну, warten, ja. Жду. — Поправляет платок. — Пенсию тут с задержкой дают. Там, говорят, вовремя. Из наших я на всю улицу одна осталась. Все уехали. Все."}, {"q": "Как вы разглядели всё в темноте?", "a": "— А что там разглядывать? Я его в лицо знаю. Он ко мне заходил, спрашивал, не надо ли кому дом. — Пауза. — Фара у «Волги» одна горела. Правая. А он прямо в свет вышел, к калитке. Это ещё до того было, как свет отключили. По радио новости как раз кончились. — Кивает на своё окно. — А потом везде темно. Только у Шмидтов в окне керосинка. Я сама с керосинкой у окна сижу, когда света нет. У меня давление, я не сплю.", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"q": "Почему вы не сообщили в милицию?", "a": "— А что я скажу? Что у соседей печку топят? Фархад сказал: люди въедут. Ну, я и думала — въехали. — Молчит. — И потом… Милицию я боюсь, извините. С советского времени боюсь. Затаскают, и к детям не выпустят. Nein, думаю, не надо мне.", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"]}]'::jsonb, '{"c2c5ba62-e24e-523f-93bc-d8909b28e717": "Тамара Фёдоровна у забора. Пальто поверх халата. Смотрит, как Сеитова поднимается из люка с пакетом.\n— Gott… Значит, был там кто-то. Был. — Прижимает руку к груди. — Я всё скажу. У меня давление, я не сплю, у окна сижу. Дом Фархад продаёт. Покупателей водил, я его в лицо знаю. В среду сказал: скоро люди въедут.\nВ пятницу смотрю — дым. Из трубы. Под навесом машина тёмная, не наша, иномарка. Парень печку топил. Высокий, молодой.\nА в субботу в четверть седьмого — «Волга» белая. Одна фара. Вышли двое: Фархад, прямо в свет, и тот парень. Парень скоро пешком ушёл. И всё. Никаких покупателей, никто больше не приезжал.\nПотом свет отключили. Везде темно, а у Шмидтов керосинка. До ночи. — Пауза. — В двадцать минут двенадцатого иномарка со двора выехала. Без фар. Я её по мотору узнала, у наших так не урчит. А «Волга» у калитки до половины второго стояла. По свежему снегу уехала.", "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba": "— Шмидты? Хорошие люди. Весной уехали, сын у них давно там. — Вздыхает. — А дом Фархад продаёт. По доверенности, я так понимаю. Покупателей водил, я его в лицо знаю. В среду сказал: скоро въедут люди. Ну, я и думала — въехали.\nВ пятницу из трубы дым. Под навесом машина тёмная, не наша. Иномарка. Печку парень топил, высокий, молодой.\nА в субботу в четверть седьмого — по радио как раз новости кончились — «Волга» белая. Одна фара горит. Вышли Фархад и тот парень. Парень пешком скоро ушёл. Покупателей никаких. Ну, ja, кто ж в темноте дом смотрит?\nПотом свет отключили. До ночи у Шмидтов одно окно светилось. Керосинка. У меня давление, я не сплю, я видела. — Пауза. — В двадцать минут двенадцатого иномарка выехала. Без фар, я по мотору узнала. А «Волга» до половины второго стояла. Уехала уже по свежему снегу.", "552b22f9-f4c6-5469-8d1c-56bde54906aa": "Тамара Фёдоровна смотрит на аппарат.\n— Телефон? Не отключали, нет. Фархад сказал: покупатели звонить будут, пусть работает. Он и платил, наверное.\n(пауза)\nА кому оттуда звонить? Там же никого нет. Не было.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "— Доверенность? Да, Отто ему оставил, когда уезжали. Дом продавать.\nКлючи тоже у него. Он и покупателей водил.\n(качает головой)\nА доллары... Ну, ja. Это уж я не знаю."}'::jsonb, '[{"id": "R18", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "Тамара Фёдоровна у забора. Пальто поверх халата. Смотрит, как Сеитова поднимается из люка с пакетом.\n— Gott… Значит, был там кто-то. Был. — Прижимает руку к груди. — Я всё скажу. У меня давление, я не сплю, у окна сижу. Дом Фархад продаёт. Покупателей водил, я его в лицо знаю. В среду сказал: скоро люди въедут.\nВ пятницу смотрю — дым. Из трубы. Под навесом машина тёмная, не наша, иномарка. Парень печку топил. Высокий, молодой.\nА в субботу в четверть седьмого — «Волга» белая. Одна фара. Вышли двое: Фархад, прямо в свет, и тот парень. Парень скоро пешком ушёл. И всё. Никаких покупателей, никто больше не приезжал.\nПотом свет отключили. Везде темно, а у Шмидтов керосинка. До ночи. — Пауза. — В двадцать минут двенадцатого иномарка со двора выехала. Без фар. Я её по мотору узнала, у наших так не урчит. А «Волга» у калитки до половины второго стояла. По свежему снегу уехала.", "grants": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"id": "R19", "on": "f1a33ded-fd6b-5c41-ad3c-f5fdbf652cba", "requires": [], "text": "— Шмидты? Хорошие люди. Весной уехали, сын у них давно там. — Вздыхает. — А дом Фархад продаёт. По доверенности, я так понимаю. Покупателей водил, я его в лицо знаю. В среду сказал: скоро въедут люди. Ну, я и думала — въехали.\nВ пятницу из трубы дым. Под навесом машина тёмная, не наша. Иномарка. Печку парень топил, высокий, молодой.\nА в субботу в четверть седьмого — по радио как раз новости кончились — «Волга» белая. Одна фара горит. Вышли Фархад и тот парень. Парень пешком скоро ушёл. Покупателей никаких. Ну, ja, кто ж в темноте дом смотрит?\nПотом свет отключили. До ночи у Шмидтов одно окно светилось. Керосинка. У меня давление, я не сплю, я видела. — Пауза. — В двадцать минут двенадцатого иномарка выехала. Без фар, я по мотору узнала. А «Волга» до половины второго стояла. Уехала уже по свежему снегу.", "grants": ["f725c4c5-f254-5c01-b718-3531a957102a"]}, {"id": "R70", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": [], "text": "Тамара Фёдоровна смотрит на аппарат.\n— Телефон? Не отключали, нет. Фархад сказал: покупатели звонить будут, пусть работает. Он и платил, наверное.\n(пауза)\nА кому оттуда звонить? Там же никого нет. Не было.", "grants": []}, {"id": "R86", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Доверенность? Да, Отто ему оставил, когда уезжали. Дом продавать.\nКлючи тоже у него. Он и покупателей водил.\n(качает головой)\nА доллары... Ну, ja. Это уж я не знаю.", "grants": []}]'::jsonb, null, false, false, true, 'https://zhdvfvrqgunjickiaoqi.supabase.co/storage/v1/object/public/location-images/v2-tamara-portrait.jpg');
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('ea6167fb-4eea-5e08-ae65-e5fce24e6a6c', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Олжас Бекенов', 'Сын двоюродной сестры Фархада, из аула под Талгаром', 'Олжас Бекенов, 22 года, грузчик на Зелёном базаре. Койка в общежитии. Ранее не судим.
Сидит на койке, смотрит в пол. На удостоверение не поднимает глаз.
— Мен не знаю ничего.', '[{"q": "Ты Игоря Сартакова знаешь?", "a": "— Не знаю. Такого не знаю.\nЯ на базаре. Мешки.\nКто такой — не знаю."}, {"q": "Где был в четверг вечером? И в субботу?", "a": "— На базаре. Потом общага.\nВахтёрша скажет. Ребята скажут. Всё."}, {"q": "Откуда у тебя три тысячи долларов?", "a": "— Заработал. Копил.\nМешки таскаю. Два года.\n(поднимает глаза и сразу опускает) Матери на дом копил.", "requires": ["46e78eb0-d057-5e5d-8a00-81457f8f3d20"]}, {"q": "Как ты с ним обращался?", "a": "— Чай носил. Хлеб.\nОн со мной через люк разговаривал. Про дочку. Ей двенадцать, говорил.\nНормальный мужик. Не ругался.\nЯ мешок ему на голову... туго не стал. Не смог. Мен не зверь.", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"]}, {"q": "Что ты скажешь матери?", "a": "— Ничего.\n(долго молчит)\nОна думает, я в городе учусь. Ойбай...\nСкажите ей — я сам. Что аке тут... Нет. Ничего не говорите.", "requires": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"]}]'::jsonb, '{"d91852b9-daca-5340-80c9-a13cffe680cc": "Кабинет. Олжас на краешке стула, руки зажаты между колен.\nНа столе — протокол сравнения купюр и показания соседки Шмидтов.\nОн смотрит в пол. Долго. Потом — быстро, не останавливаясь:\n— Ойбай... Ладно. Я.\nЯ его взял. У ворот, в четверг. Темно уже было.\nМашину его к Шмидтам перегнал, под навес. Водить умею. Прав нет.\nВ подвале у немцев держал. Кормил. Чай носил. Не бил, клянусь.\nМатери его из автоматов звонил. А в субботу на остановке автомат сломан — я из того дома позвонил.\nПакет на остановке я забрал. Деньги оттуда, да.\n(поднимает голову) Но аке ни при чём! Слышите? Я сам придумал. Сам.\nУтром его отпустили... ну, отпустил кто-то. Машина там же стояла, под навесом. Сел, поехал к себе на дачу. И угорел.\nБог наказал. Я его не трогал.", "54bf13bc-3525-5eec-9441-609d8ee21f59": "Кабинет. На столе вспоротый мешок с рисом, протокол обыска. Олжас и Фархад друг напротив друга. Понятой смотрит в стену.\nВы зачитываете заключение Кана: задушен в субботу около десяти вечера, в машину посажен мёртвым. И говорите, где лежали остальные деньги.\nОлжас поворачивается к дяде.\n— Аке... Ты же сказал — утром отпустишь. За городом.\n(голос садится)\nТы меня за остановкой подобрал. Мы вдвоём приехали. Там, кроме нас, только он был.\nЯ тебе в четверть седьмого всё передал. Как он просил. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» от тебя пахло. Когда ты ему воду спускал.\nТы молчал. Три тысячи мне отсчитал.\nБез четверти семь: иди в общагу. Я пошёл.\n(закрывает лицо руками) Это я тебе сказал. Если б я не сказал...", "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4": "Кабинет. Перед Олжасом журнал вахтёрши и заключение Кана: царапины на кисти дяди. Задушен в субботу около десяти вечера.\n— Ну да. В общаге был. С полвосьмого.\n(смотрит на строчку, потом на бумагу Кана)\nЗначит... Я в общаге. А с ним аке остался. Один.\nМы ж вдвоём туда приехали. Никого больше не было.\nИ Игорь его ногтями... в десять вечера...\n(пауза)\nЯ ему в четверть седьмого передал. Слова Игоря. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» пахло, когда воду спускал.\nАке ничего не сказал. Деньги забрал, мне три тысячи отсчитал.\nБез четверти семь отправил: иди, утром за городом его отпущу.\nОйбай... Он же сказал — никто не пострадает.", "87af9a91-8540-5177-bdd6-3e156802fc75": "Перед Олжасом серый шарф из подвала. Вы пересказываете, что видели Данияр на остановке и соседка у дома Шмидтов: высокий, молодой, спортивная куртка, ушанка. Печь топил.\nОлжас смотрит на шарф. Глаз не отводит.\n— Он мёрз там...\n(и сразу, быстро)\nЯ его взял. В четверг, у ворот. Темно было.\nМашину к Шмидтам перегнал. Водить умею, прав нет.\nВ подвале держал. Матери его из автоматов звонил. А в субботу — из того дома, там телефон.\nПакет на остановке я забрал.\nНо аке ни при чём! Я сам придумал, слышите? Сам.\nУтром его отпустили, машину отдали — там же стояла, под навесом. Он на дачу поехал. И угорел. Бог наказал. Не я.\nСосед по комнате перестаёт притворяться спящим. На запястьях Олжаса щёлкают наручники.", "46e78eb0-d057-5e5d-8a00-81457f8f3d20": "— Моё это. Куртка, шапка, ботинки.\nДеньги? Заработал. На базаре грузил, ночами.\n(смотрит в сторону)\nЧто, нельзя?", "9281d556-d163-5537-a0e2-e4cd2e635ba5": "— Я же сказал уже. Был там. Держал его.\n(смотрит в пол)\nА дальше я не знаю. Меня там не было.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "— Аке руку поранил? Не знаю.\nЯ его давно не видел. Работа, база.\n(трёт ладони о колени)"}'::jsonb, '[{"id": "R25", "on": "d91852b9-daca-5340-80c9-a13cffe680cc", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a"], "text": "Кабинет. Олжас на краешке стула, руки зажаты между колен.\nНа столе — протокол сравнения купюр и показания соседки Шмидтов.\nОн смотрит в пол. Долго. Потом — быстро, не останавливаясь:\n— Ойбай... Ладно. Я.\nЯ его взял. У ворот, в четверг. Темно уже было.\nМашину его к Шмидтам перегнал, под навес. Водить умею. Прав нет.\nВ подвале у немцев держал. Кормил. Чай носил. Не бил, клянусь.\nМатери его из автоматов звонил. А в субботу на остановке автомат сломан — я из того дома позвонил.\nПакет на остановке я забрал. Деньги оттуда, да.\n(поднимает голову) Но аке ни при чём! Слышите? Я сам придумал. Сам.\nУтром его отпустили... ну, отпустил кто-то. Машина там же стояла, под навесом. Сел, поехал к себе на дачу. И угорел.\nБог наказал. Я его не трогал.", "grants": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"]}, {"id": "R26", "on": "54bf13bc-3525-5eec-9441-609d8ee21f59", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "107fcb2c-e909-5f81-bba4-d218265227c5"], "text": "Кабинет. На столе вспоротый мешок с рисом, протокол обыска. Олжас и Фархад друг напротив друга. Понятой смотрит в стену.\nВы зачитываете заключение Кана: задушен в субботу около десяти вечера, в машину посажен мёртвым. И говорите, где лежали остальные деньги.\nОлжас поворачивается к дяде.\n— Аке... Ты же сказал — утром отпустишь. За городом.\n(голос садится)\nТы меня за остановкой подобрал. Мы вдвоём приехали. Там, кроме нас, только он был.\nЯ тебе в четверть седьмого всё передал. Как он просил. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» от тебя пахло. Когда ты ему воду спускал.\nТы молчал. Три тысячи мне отсчитал.\nБез четверти семь: иди в общагу. Я пошёл.\n(закрывает лицо руками) Это я тебе сказал. Если б я не сказал...", "grants": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"]}, {"id": "R41", "on": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4", "requires": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d", "7d1a9a15-62a5-51f0-98d5-bf6ac0dc1ce3"], "text": "Кабинет. Перед Олжасом журнал вахтёрши и заключение Кана: царапины на кисти дяди. Задушен в субботу около десяти вечера.\n— Ну да. В общаге был. С полвосьмого.\n(смотрит на строчку, потом на бумагу Кана)\nЗначит... Я в общаге. А с ним аке остался. Один.\nМы ж вдвоём туда приехали. Никого больше не было.\nИ Игорь его ногтями... в десять вечера...\n(пауза)\nЯ ему в четверть седьмого передал. Слова Игоря. «Фархад, я тебя узнал. Бери деньги и отпусти, никому не скажу».\nОн тебя через мешок узнал, аке. По кашлю. И «Беломором» пахло, когда воду спускал.\nАке ничего не сказал. Деньги забрал, мне три тысячи отсчитал.\nБез четверти семь отправил: иди, утром за городом его отпущу.\nОйбай... Он же сказал — никто не пострадает.", "grants": ["3ad29f0f-a1d4-5f8d-abca-4dd530eabf4c"]}, {"id": "R42", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": ["f725c4c5-f254-5c01-b718-3531a957102a", "ea60506a-dfdb-5176-a63a-2fd3c47f8b6e"], "text": "Перед Олжасом серый шарф из подвала. Вы пересказываете, что видели Данияр на остановке и соседка у дома Шмидтов: высокий, молодой, спортивная куртка, ушанка. Печь топил.\nОлжас смотрит на шарф. Глаз не отводит.\n— Он мёрз там...\n(и сразу, быстро)\nЯ его взял. В четверг, у ворот. Темно было.\nМашину к Шмидтам перегнал. Водить умею, прав нет.\nВ подвале держал. Матери его из автоматов звонил. А в субботу — из того дома, там телефон.\nПакет на остановке я забрал.\nНо аке ни при чём! Я сам придумал, слышите? Сам.\nУтром его отпустили, машину отдали — там же стояла, под навесом. Он на дачу поехал. И угорел. Бог наказал. Не я.\nСосед по комнате перестаёт притворяться спящим. На запястьях Олжаса щёлкают наручники.", "grants": ["0146fe89-1029-5d65-87bb-f750dfe7ad2d"]}, {"id": "R81", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "— Моё это. Куртка, шапка, ботинки.\nДеньги? Заработал. На базаре грузил, ночами.\n(смотрит в сторону)\nЧто, нельзя?", "grants": []}, {"id": "R82", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Я же сказал уже. Был там. Держал его.\n(смотрит в пол)\nА дальше я не знаю. Меня там не было.", "grants": []}, {"id": "R90", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "— Аке руку поранил? Не знаю.\nЯ его давно не видел. Работа, база.\n(трёт ладони о колени)", "grants": []}]'::jsonb, null, false, true, true, (select portrait_url from characters where name ilike '%Олжас%' and case_id <> '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and portrait_url is not null limit 1));
insert into characters (id, case_id, location_id, name, role, intro_text, fixed_questions, reactions, reaction_rules, unlock_evidence_ids, is_expert, is_suspect, is_case_subject, portrait_url) values ('ad04679a-62fd-52ac-a043-6e04873ad6b3', '029e23c3-01e0-5d19-a0e7-3e0c2446ebab', 'ee497c59-0b63-50e6-91fc-8c67893c99ed', 'Роза-апа Сагинтаева', 'Вахтёрша общежития у Зелёного базара', 'Роза-апа Сагинтаева, вахтёрша общежития. За стеклом вахты, в пуховом платке. Радиоточка, ключи на гвоздиках.
— Вы к кому? А, из милиции. Ну, проходите. Только ноги вытирайте, я полы мыла.', '[{"q": "Бекенов из 412-й — что за парень?", "a": "— Олжас? Тихий. Из аула. Техникум бросил, на базаре грузит. Матери деньги отправляет.\n(поправляет платок)\nНе пьёт, не дерётся. Таких бы больше."}, {"q": "Когда Бекенов пришёл в субботу?", "a": "— А вот журнал. У меня все записаны, кто вошёл, кто вышел.\n(разворачивает журнал к вам)\nПришёл в полвосьмого. Мокрый весь. И сразу наверх. Не выходил он: у меня с одиннадцати дверь на замке, ключ вот он.\nРебята в комнате скажут, они в карты до ночи играли. А он лежал. Лицом к стене.", "grants_evidence_id": "ed68230f-dcda-56e7-a77c-ecd7a4cc05a4"}]'::jsonb, '{}'::jsonb, '[]'::jsonb, null, false, false, true, null);

-- 5. Обманки в обыске
